insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q04', 'a1-m1-l1', 4, 'word_selection', '«До свидания» — xayrlashuvdagi asosiy ibora («ko''rishguncha» degan ma''noda). Kundalik qisqa varianti — «Пока».', '{"promptUz":"Xayr (kundalik xayrlashuv)","options":["До свидания","Привет","Спасибо","Пожалуйста"],"correctIndex":0}'::jsonb, 'Xayr (kundalik xayrlashuv)', array['До свидания', 'Привет', 'Спасибо', 'Пожалуйста'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q05', 'a1-m1-l1', 5, 'true_false', '«До svdания!» — to''g''ri tarjima: xayrlashuvda aytiladi va «Xayr!» degan ma''noni bildiradi.', '{"ruText":"До свидания!","uzTranslation":"Xayr!","isTrue":true}'::jsonb, 'До свидания!', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q06', 'a1-m1-l1', 6, 'sentence_building', '«Привет, как дела?» — eng ko''p ishlatiladigan salom: «Salom! Qalaysiz?». So''zlar o''z tartibida joylashadi.', '{"correct":["Привет",",","как","дела","?"],"distractors":["спасибо","до","свидания"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q07', 'a1-m1-l1', 7, 'fill_blank', '«Меня зовут...» — «Mening ismim...» degan tayyor ibora. «зовут» fe''li «deb atashadi» ma''nosini beradi.', '{"sentence":"Здравствуйте, меня ___ Анна.","options":["зовут","зовёшь","зовете","зовутся"],"correctIndex":0}'::jsonb, 'Здравствуйте, меня ___ Анна.', array['зовут', 'зовёшь', 'зовете', 'зовутся'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q08', 'a1-m1-l1', 8, 'multiple_choice', '«Как дела?» — hol so''rash iborasi. Javoban «Хорошо» (Yaxshi) yoki «Плохо» (Yomon) deyiladi.', '{"prompt":"«Как дела?» qaysi ma''noda ishlatiladi?","promptLang":"uz","options":["Rahmat so''rash","Hol so''rash","Xayr aytish","Kechirish so''rash"],"correctIndex":1}'::jsonb, '«Как дела?» qaysi ma''noda ishlatiladi?', array['Rahmat so''rash', 'Hol so''rash', 'Xayr aytish', 'Kechirish so''rash'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q09', 'a1-m1-l1', 9, 'translation', '«Xayr!» — xayrlashuv so''zi. Rus tilida eng ko''p «До свидания» (norasmiy variant — «Пока») ishlatiladi.', '{"direction":"uz_to_ru","source":"Xayr!","accepted":["до свидания","пока","до свиданья"]}'::jsonb, 'Xayr!', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q10', 'a1-m1-l1', 10, 'word_matching', 'Salomlashish iboralari: «Привет» — Salom, «До свидания» — Xayr, «Доброе утро» — Xayrli tong, «Спокойной ночи» — Xayrli tun.', '{"pairs":[{"ru":"Привет","uz":"Salom"},{"ru":"До свидания","uz":"Xayr"},{"ru":"Доброе утро","uz":"Xayrli tong"},{"ru":"Спокойной ночи","uz":"Xayrli tun"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q11', 'a1-m1-l1', 11, 'listening', '«Привет! Как дела?» — «Salom! Qalaysiz?». «Как дела» so''zma-so''z «qanday ishlar» demakdir.', '{"speakText":"Привет! Как дела?","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Salom! Qalaysiz?","Xayr! Rahmat!","Kechirasiz, kim?","Xayrli tong!"],"correctIndex":0}'::jsonb, 'Привет! Как дела?', array['Salom! Qalaysiz?', 'Xayr! Rahmat!', 'Kechirasiz, kim?', 'Xayrli tong!'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l1-q12', 'a1-m1-l1', 12, 'multiple_choice', '«Спасибо» — «Rahmat». Javob varianti — «Пожалуйста» (Iltimos / Arzimaydi).', '{"prompt":"«Спасибо» so''zi nima degani?","promptLang":"uz","options":["Iltimos","Rahmat","Kechirasiz","Ha"],"correctIndex":1}'::jsonb, '«Спасибо» so''zi nima degani?', array['Iltimos', 'Rahmat', 'Kechirasiz', 'Ha'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q01', 'a1-m1-l2', 1, 'multiple_choice', '«Меня зовут Азиз» — «Mening ismim Aziz». Bu tanishuvdagi eng ko''p ishlatiladigan ibora.', '{"prompt":"«Меня зовут Азиз» degan gapning to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Mening ismim Aziz","Bu menim do''stim Aziz","Men talabaman Aziz","Aziz xursand"],"correctIndex":0}'::jsonb, '«Меня зовут Азиз» degan gapning to''g''ri tarjimasini tanlang.', array['Mening ismim Aziz', 'Bu menim do''stim Aziz', 'Men talabaman Aziz', 'Aziz xursand'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q02', 'a1-m1-l2', 2, 'translation', '«Приятно познакомиться» — tanishuvdan keyin aytiladigan xushmuomala ibora: «Tanishganimdan xursandman».', '{"direction":"ru_to_uz","source":"Приятно познакомиться!","accepted":["tanishganimdan xursandman","tanishganimizdan xursandman","tanishganimiz yoqimli"]}'::jsonb, 'Приятно познакомиться!', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q03', 'a1-m1-l2', 3, 'multiple_choice', '«Как вас зовут?» — rasmiy ravishda ism so''ratadigan savol («siz» shakli). Kundalik varianti — «Как тебя зовут?».', '{"prompt":"«Как вас зовут?» — bu qanday savol?","promptLang":"uz","options":["Ismingiz nima?","Qayerdasiz?","Nechaga to''ldingiz?","Qalaysiz?"],"correctIndex":0}'::jsonb, '«Как вас зовут?» — bu qanday savol?', array['Ismingiz nima?', 'Qayerdasiz?', 'Nechaga to''ldingiz?', 'Qalaysiz?'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q04', 'a1-m1-l2', 4, 'fill_blank', '«Меня зовут Лейла» — «Leylaning ismi...» / «Meni Leyla deb atashadi». «зовут» doim 3-shaxs ko''plikda turadi.', '{"sentence":"Меня ___ Лейла.","options":["зовут","зовёшь","зовете","зову"],"correctIndex":0}'::jsonb, 'Меня ___ Лейла.', array['зовут', 'зовёшь', 'зовете', 'зову'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q05', 'a1-m1-l2', 5, 'word_selection', '«Знакомство» — «tanishuv». «Знакомиться» fe''li — «tanishmoq».', '{"promptUz":"Tanishuv","options":["знакомство","привет","друг","урок"],"correctIndex":0}'::jsonb, 'Tanishuv', array['знакомство', 'привет', 'друг', 'урок'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q06', 'a1-m1-l2', 6, 'listening', '«Меня зовут Ойбек» — «Mening ismim Oybek». «Меня» — meni (kelishik shakli), «зовут» — deb ataydilar.', '{"speakText":"Меня зовут Ойбек.","promptUz":"Esiting va to''g''ri javobni tanlang.","options":["Mening ismim Oybek","Bu Oybek do''stim","Oybek hozir keladi","Oybek o''qituvchi"],"correctIndex":0}'::jsonb, 'Меня зовут Ойбек.', array['Mening ismim Oybek', 'Bu Oybek do''stim', 'Oybek hozir keladi', 'Oybek o''qituvchi'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q07', 'a1-m1-l2', 7, 'true_false', '«Я ученик» — «Men o''quvchiman». «Ученик» — maktab o''quvchisi, «студент» — talaba.', '{"ruText":"Я ученик.","uzTranslation":"Men o''quvchiman.","isTrue":true}'::jsonb, 'Я ученик.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q08', 'a1-m1-l2', 8, 'word_matching', 'Tanishuv iboralari: «Меня зовут» — Mening ismim, «Как вас зовут» — Ismingiz nima, «Ученик» — O''quvchi, «Друг» — Do''stim.', '{"pairs":[{"ru":"Меня зовут","uz":"Mening ismim"},{"ru":"Как вас зовут","uz":"Ismingiz nima"},{"ru":"Ученик","uz":"O''quvchi"},{"ru":"Друг","uz":"Do''stim"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q09', 'a1-m1-l2', 9, 'translation', '«Как вас зовут?» — rasmiy shakl. «siz» bilan murojaat qilinadi, chunki bu hurmatli savol.', '{"direction":"uz_to_ru","source":"Ismingiz nima?","accepted":["как вас зовут","как вас зовут?"]}'::jsonb, 'Ismingiz nima?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q10', 'a1-m1-l2', 10, 'sentence_building', '«Это мой друг» — «Bu menim do''stim». «мой» — menim (erkak jins uchun).', '{"correct":["Это","мой","друг","."],"distractors":["учитель","ваш","сестра"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q11', 'a1-m1-l2', 11, 'multiple_choice', '«Приятно познакомиться» — yangi odam bilan ilk bor tanishganda aytiladi.', '{"prompt":"«Приятно познакомиться» iborasi qachon aytiladi?","promptLang":"uz","options":["Yangi odam bilan tanishganda","Xayrlashganda","Rahmat aytganda","Kechirasiz so''raganda"],"correctIndex":0}'::jsonb, '«Приятно познакомиться» iborasi qachon aytiladi?', array['Yangi odam bilan tanishganda', 'Xayrlashganda', 'Rahmat aytganda', 'Kechirasiz so''raganda'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l2-q12', 'a1-m1-l2', 12, 'fill_blank', '«Это мой друг» — «мой» (menim) ot qoshida turadi. «моя» ayol jinsidagi narsalar uchun: «моя мама».', '{"sentence":"Это ___ друг.","options":["мой","моя","мои","его"],"correctIndex":0}'::jsonb, 'Это ___ друг.', array['мой', 'моя', 'мои', 'его'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q01', 'a1-m1-l3', 1, 'multiple_choice', '«Мне 12 лет» — so''zma-so''z «menga 12 yosh», o''zbek tilida «Mening yoshim 12» deyiladi.', '{"prompt":"«Мне 12 лет» ning to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Mening yoshim 12","Mening do''stim 12","Mening sinfim 12","Mening uchun 12"],"correctIndex":0}'::jsonb, '«Мне 12 лет» ning to''g''ri tarjimasini tanlang.', array['Mening yoshim 12', 'Mening do''stim 12', 'Mening sinfim 12', 'Mening uchun 12'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q02', 'a1-m1-l3', 2, 'translation', '«Сколько тебе лет?» — yosh so''ratish savoli. «сколько» — nechta, necha.', '{"direction":"uz_to_ru","source":"Yoshing nechaga to''ladi?","accepted":["сколько тебе лет","сколько тебе лет?"]}'::jsonb, 'Yoshing nechaga to''ladi?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q03', 'a1-m1-l3', 3, 'fill_blank', 'Rus tilida 5–20 gacha sonlardan keyin doim «лет» ishlatiladi: «Ему пять лет» (Unga 5 yosh).', '{"sentence":"Ему пять ___.","options":["лет","год","года","лета"],"correctIndex":0}'::jsonb, 'Ему пять ___.', array['лет', 'год', 'года', 'лета'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q04', 'a1-m1-l3', 4, 'listening', '«Мне десять лет» — «Mening yoshim 10». «десять» — o''n. Eshitilgan sonni aniq tinglang.', '{"speakText":"Мне десять лет.","promptUz":"Esiting va yoshni to''g''ri tanlang.","options":["Mening yoshim 10","Mening yoshim 11","Mening yoshim 20","Mening yoshim 7"],"correctIndex":0}'::jsonb, 'Мне десять лет.', array['Mening yoshim 10', 'Mening yoshim 11', 'Mening yoshim 20', 'Mening yoshim 7'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q05', 'a1-m1-l3', 5, 'word_selection', '«Возраст» — yosh (umumiy). «Год» — yil (vaqt birligi).', '{"promptUz":"Yosh (son)","options":["возраст","год","время","день"],"correctIndex":0}'::jsonb, 'Yosh (son)', array['возраст', 'год', 'время', 'день'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q06', 'a1-m1-l3', 6, 'multiple_choice', '«Сколько тебе лет?» — shaxsning yoshini so''raydi. Javob: «Мне двадцать лет» (Mening yoshim 20).', '{"prompt":"«Сколько тебе лет?» savoli nimani so''raydi?","promptLang":"uz","options":["Yoshni","Ismni","Manzilni","Vaqtni"],"correctIndex":0}'::jsonb, '«Сколько тебе лет?» savoli nimani so''raydi?', array['Yoshni', 'Ismni', 'Manzilni', 'Vaqtni'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
