insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l3-q11', 'a1-m1-l3', 11, 'multiple_choice', '«Год» — yil. «Я родился в две тысячи двенадцатом году» — Men 2012-yilda tug''ilganman.', '{"prompt":"«Год» so''zi nima degani?","promptLang":"uz","options":["Oy","Yil","Kun","Hafta"],"correctIndex":1}'::jsonb, '«Год» so''zi nima degani?', array['Oy', 'Yil', 'Kun', 'Hafta'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q01', 'a1-m1-l4', 1, 'multiple_choice', '«Откуда ты?» — «Qayerdansan?». «Откуда» — qayerdan (kelishik ma''nosi).', '{"prompt":"«Откуда ты?» nimani so''raydi?","promptLang":"uz","options":["Manzilni (qayerdan)","Yoshni","Ismni","Ishni"],"correctIndex":0}'::jsonb, '«Откуда ты?» nimani so''raydi?', array['Manzilni (qayerdan)', 'Yoshni', 'Ismni', 'Ishni'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q02', 'a1-m1-l4', 2, 'translation', '«Я из Узбекистана» — «Men O''zbekistondaman». «из» — … dan, kelishik qo''shimchasi.', '{"direction":"ru_to_uz","source":"Я из Узбекистана.","accepted":["men o''zbekistondaman","men o''zbekistondanman"]}'::jsonb, 'Я из Узбекистана.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q03', 'a1-m1-l4', 3, 'fill_blank', '«Я из Узбекистана» — «из» + joy nomi = … dan. «Я в Ташкенте» — «в» = … da (yashash joyi).', '{"sentence":"Я ___ Узбекистана.","options":["из","в","на","до"],"correctIndex":0}'::jsonb, 'Я ___ Узбекистана.', array['из', 'в', 'на', 'до'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q04', 'a1-m1-l4', 4, 'listening', '«Я живу в Ташкенте» — «Men Toshkentda yashayman». «живу» — yashayman.', '{"speakText":"Я живу в Ташкенте.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Men Toshkentda yashayman","Men Toshkentdanman","Men Samarqandda yashayman","Toshkent juda katta"],"correctIndex":0}'::jsonb, 'Я живу в Ташкенте.', array['Men Toshkentda yashayman', 'Men Toshkentdanman', 'Men Samarqandda yashayman', 'Toshkent juda katta'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
