insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q08', 'a1-m1-l5', 8, 'word_matching', 'Asosiy suhbat iboralari: Привет — Salom, Как дела — Qalaysiz, До свидания — Xayr, Спасибо — Rahmat.', '{"pairs":[{"ru":"Привет","uz":"Salom"},{"ru":"Как дела","uz":"Qalaysiz"},{"ru":"До свидания","uz":"Xayr"},{"ru":"Спасибо","uz":"Rahmat"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q09', 'a1-m1-l5', 9, 'translation', '«Qayerdansan?» — «Откуда ты?». Bu tanishuvdagi keyingi tabiiy savol.', '{"direction":"uz_to_ru","source":"Qayerdansan?","accepted":["откуда ты","откуда ты?"]}'::jsonb, 'Qayerdansan?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q10', 'a1-m1-l5', 10, 'multiple_choice', '«А тебя?» — hamkor savol: «Seningizniki-chi?» / «A sening-chi?». Suhbat davom etadi.', '{"prompt":"«А тебя?» — bu qanday savol?","promptLang":"uz","options":["Hamkor savol («Sening-chi?»)","Rasmiy savol","Rad javobi","Tanqidiy savol"],"correctIndex":0}'::jsonb, '«А тебя?» — bu qanday savol?', array['Hamkor savol («Sening-chi?»)', 'Rasmiy savol', 'Rad javobi', 'Tanqidiy savol'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q11', 'a1-m1-l5', 11, 'listening', '«Меня зовут Дилшод» — «Mening ismim Dilshod». «зовут» — deb ataydilar.', '{"speakText":"Меня зовут Дилшод.","promptUz":"Esiting va to''g''ri javobni tanlang.","options":["Mening ismim Dilshod","Bu menim do''stim Dilshod","Dilshod hozir keladi","Dilshod o''qituvchi"],"correctIndex":0}'::jsonb, 'Меня зовут Дилшод.', array['Mening ismim Dilshod', 'Bu menim do''stim Dilshod', 'Dilshod hozir keladi', 'Dilshod o''qituvchi'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q12', 'a1-m1-l5', 12, 'fill_blank', '«Я из России, а ты?» — «Rossiyadanman, a sen?». «из» — … dan.', '{"sentence":"— Откуда ты? — Я ___ России, а ты?","options":["из","в","с","к"],"correctIndex":0}'::jsonb, '— Откуда ты? — Я ___ России, а ты?', array['из', 'в', 'с', 'к'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q01', 'a1-m2-l1', 1, 'multiple_choice', 'Rus alifbosi — kirill yozuvi: 10 ta unli harf (а, о, у, ы, э, и, е, ё, ю, я), 21 ta undosh harf va 2 ta belgi (ъ, ь) — jami 33 ta harf.', '{"prompt":"Rus alifbisida nechta harf bor?","promptLang":"uz","options":["26","33","30","36"],"correctIndex":1}'::jsonb, 'Rus alifbisida nechta harf bor?', array['26', '33', '30', '36'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q02', 'a1-m2-l1', 2, 'translation', '«Алфавит» — barcha harflarning tartibli ro''yxati, ya''ni alifbo. O''zbekcha aynan «alifbo» deb tarjima qilinadi.', '{"direction":"ru_to_uz","source":"Алфавит","accepted":["alifbo","harf to''plami"]}'::jsonb, 'Алфавит', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q03', 'a1-m2-l1', 3, 'word_matching', '«буква» — harf, «алфавит» — alifbo; «гласная» — unli harf, «согласная» — undosh harf.', '{"pairs":[{"ru":"буква","uz":"harf"},{"ru":"алфавит","uz":"alifbo"},{"ru":"гласная буква","uz":"unli harf"},{"ru":"согласная буква","uz":"undosh harf"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q04', 'a1-m2-l1', 4, 'multiple_choice', 'Rus harflari kirill yozuviga tegishli (а, б, в...). Lotin yozuvi (a, b, c) esa o''zbek va ingliz tilida ishlatiladi.', '{"prompt":"Quyidagilardan qaysi biri kirill alifbosiga tegishli?","promptLang":"uz","options":["а, б, в","a, b, c","alif, ba, ta","あ, い, う"],"correctIndex":0}'::jsonb, 'Quyidagilardan qaysi biri kirill alifbosiga tegishli?', array['а, б, в', 'a, b, c', 'alif, ba, ta', 'あ, い, う'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q05', 'a1-m2-l1', 5, 'true_false', 'To''g''ri: 10 unli + 21 undosh + 2 belgi (ъ, ь) = 33 ta harf. Rus alifbosi shu tartibda yoziladi.', '{"ruText":"Русский алфавит состоит из 33 букв.","uzTranslation":"Rus alifbosi 33 ta harfdan iborat.","isTrue":true}'::jsonb, 'Русский алфавит состоит из 33 букв.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q06', 'a1-m2-l1', 6, 'fill_blank', '«В русском алфавите 33 буквы» — rus alifbisida 33 ta harf bor. Kirill yozuvi lotin yozuvidan butunlay farq qiladi.', '{"sentence":"В русском алфавите ___ буквы.","options":["30","28","33","26"],"correctIndex":2}'::jsonb, 'В русском алфавите ___ буквы.', array['30', '28', '33', '26'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q07', 'a1-m2-l1', 7, 'listening', '«Русский алфавит» — «Rus alifbosi». «русский» — ruscha, «алфавит» — alifbo degan ma''noni bildiradi.', '{"speakText":"Русский алфавит.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Rus tili","Rus harflari","Rus alifbosi","O''zbek alifbosi"],"correctIndex":2}'::jsonb, 'Русский алфавит.', array['Rus tili', 'Rus harflari', 'Rus alifbosi', 'O''zbek alifbosi'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q08', 'a1-m2-l1', 8, 'word_selection', '«Буква» — harf. «Слово» — so''z, «брат» — aka-uka, «дом» — uy (boshqa so''zlar).', '{"promptUz":"Harf","options":["буква","слово","брат","дом"],"correctIndex":0}'::jsonb, 'Harf', array['буква', 'слово', 'брат', 'дом'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q09', 'a1-m2-l1', 9, 'sentence_building', '«Это русский алфавит» — «Bu rus alifbosi». «русский» sifati «алфавит» so''zidan oldin turadi.', '{"correct":["Это","русский","алфавит","."],"distractors":["буква","казахский","она"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q10', 'a1-m2-l1', 10, 'translation', '«Bu rus alifbosi» — «Это русский алфавит». «это» — bu (ko''rsatma so''zi), «русский» — ruscha/rus.', '{"direction":"uz_to_ru","source":"Bu rus alifbosi.","accepted":["это русский алфавит","это русский алфавит?"]}'::jsonb, 'Bu rus alifbosi.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q11', 'a1-m2-l1', 11, 'multiple_choice', '«Буква» — harf. «Слово» — so''z, «предложение» — gap, «цифра» — raqam deganlarini bilib oling.', '{"prompt":"«Буква» so''zi nima degani?","promptLang":"uz","options":["So''z","Harf","Gap","Raqam"],"correctIndex":1}'::jsonb, '«Буква» so''zi nima degani?', array['So''z', 'Harf', 'Gap', 'Raqam'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l1-q12', 'a1-m2-l1', 12, 'listening', 'Bu rus alifbosining birinchi harflari: а, б, в, г, д. Raqamlar esa boshqacha yoziladi: 1, 2, 3...', '{"speakText":"А, Б, В, Г, Д.","promptUz":"Esiting va to''g''ri javobni tanlang.","options":["Bu raqamlar","Bu o''zbek harflari","Bu rus harflari","Bu lotin harflari"],"correctIndex":2}'::jsonb, 'А, Б, В, Г, Д.', array['Bu raqamlar', 'Bu o''zbek harflari', 'Bu rus harflari', 'Bu lotin harflari'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q01', 'a1-m2-l2', 1, 'multiple_choice', 'Unli harf — og''izni ochib ovoz chiqaradigan harf: а, о, у, ы, э, и. «б», «т», «с» esa undosh harflar.', '{"prompt":"Quyidagilardan qaysi biri unli harf?","promptLang":"uz","options":["б","о","т","с"],"correctIndex":1}'::jsonb, 'Quyidagilardan qaysi biri unli harf?', array['б', 'о', 'т', 'с'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q02', 'a1-m2-l2', 2, 'word_selection', '«Гласная» — unli harf (а, о, у, ы, э, и). «Согласная» — undosh harf, «слово» — so''z.', '{"promptUz":"Unli harf","options":["гласная","слово","буква","согласная"],"correctIndex":0}'::jsonb, 'Unli harf', array['гласная', 'слово', 'буква', 'согласная'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q03', 'a1-m2-l2', 3, 'fill_blank', 'Urg''u tushmagan «о» odatda «а» kabi o''qiladi: «молоко» → [малако]. Bu rus tilidagi asosiy talaffuz qoidalaridan biri.', '{"sentence":"В слове «молоко» буква «о» читается как ___.","options":["о","у","э","а"],"correctIndex":3}'::jsonb, 'В слове «молоко» буква «о» читается как ___.', array['о', 'у', 'э', 'а'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q04', 'a1-m2-l2', 4, 'translation', '«Unli harf» — «гласная буква». «гласная» — unli, «согласная» esa undosh harf deyiladi.', '{"direction":"uz_to_ru","source":"Unli harf","accepted":["гласная буква","гласная"]}'::jsonb, 'Unli harf', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q05', 'a1-m2-l2', 5, 'true_false', '«ы» — unli harf, u og''iz orqasida ovoz chiqaradi, shuning uchun «undosh harf» degan tarjima noto''g''ri.', '{"ruText":"Буква «ы» — гласная.","uzTranslation":"«ы» harfi undosh harf.","isTrue":false}'::jsonb, 'Буква «ы» — гласная.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q06', 'a1-m2-l2', 6, 'listening', 'Bu uchta unli harf: а, о, у. Ular og''izni ochib ovoz chiqaradi, undosh harflar esa lab, til va tomoq orqali chiqadi.', '{"speakText":"А, О, У.","promptUz":"Esiting va to''g''ri javobni tanlang.","options":["Bu raqamlar","Bu unli harflar","Bu undosh harflar","Bu so''zlar"],"correctIndex":1}'::jsonb, 'А, О, У.', array['Bu raqamlar', 'Bu unli harflar', 'Bu undosh harflar', 'Bu so''zlar'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q07', 'a1-m2-l2', 7, 'multiple_choice', 'Urg''u tushmagan «о» «а» kabi o''qiladi: «молодой» → [маладой]. Urg''u tushgan «о» esa «о» bo''lib qoladi.', '{"prompt":"«Молодой» so''zidagi urg''u tushmagan «о» qanday o''qiladi?","promptLang":"uz","options":["«о» kabi","«ы» kabi","«и» kabi","«а» kabi"],"correctIndex":3}'::jsonb, '«Молодой» so''zidagi urg''u tushmagan «о» qanday o''qiladi?', array['«о» kabi', '«ы» kabi', '«и» kabi', '«а» kabi'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q08', 'a1-m2-l2', 8, 'sentence_building', '«Мы учим русский алфавит» — «Biz rus alifbosini o''rganmoqdamiz». «учим» — o''rganmoqdamiz (biz shakli).', '{"correct":["Мы","учим","русский","алфавит","."],"distractors":["буква","говорят","она"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q09', 'a1-m2-l2', 9, 'word_matching', '«гласная» — unli; «мама» — ona; «да» — ha; «нет» — yo''q. Bu so''zlar keyingi o''qish mashqlari uchun asos bo''ladi.', '{"pairs":[{"ru":"гласная","uz":"unli"},{"ru":"мама","uz":"ona"},{"ru":"да","uz":"ha"},{"ru":"нет","uz":"yo''q"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q10', 'a1-m2-l2', 10, 'fill_blank', '«мама» = м + а + м + а: «а» — unli, «м» — undosh. Har bir so''z unli va undosh harflardan iborat bo''ladi.', '{"sentence":"Слова «мама» и «папа» состоят из ___ и согласных букв.","options":["твёрдых","мягких","гласных","ударных"],"correctIndex":2}'::jsonb, 'Слова «мама» и «папа» состоят из ___ и согласных букв.', array['твёрдых', 'мягких', 'гласных', 'ударных'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q11', 'a1-m2-l2', 11, 'translation', '«Мама» — ona, «папа» — ota. «и» — va (ulash so''zi), shu sababli «Мама и папа» = «Ona va ota».', '{"direction":"ru_to_uz","source":"Мама и папа.","accepted":["ona va ota","ona va otam"]}'::jsonb, 'Мама и папа.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l2-q12', 'a1-m2-l2', 12, 'true_false', 'To''g''ri: bu to''rtala unli harf. Ular oldida «й» kabi tovush eshitiladi: «я» — [йа], «ё» — [йо], «ю» — [йу].', '{"ruText":"Буквы «е», «ё», «ю», «я» — тоже гласные.","uzTranslation":"«е», «ё», «ю», «я» harflari ham unli harflar.","isTrue":true}'::jsonb, 'Буквы «е», «ё», «ю», «я» — тоже гласные.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q01', 'a1-m2-l3', 1, 'multiple_choice', '21 ta undosh harf bor (б, в, г, д... ш, щ). Qolgan 10 ta unli harf va 2 ta belgi (ъ, ь) bilan jami 33 ta harf.', '{"prompt":"Rus tilida nechta undosh harf bor?","promptLang":"uz","options":["10","21","22","20"],"correctIndex":1}'::jsonb, 'Rus tilida nechta undosh harf bor?', array['10', '21', '22', '20'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q02', 'a1-m2-l3', 2, 'word_matching', '«согласная» — undosh; «мягкий знак ь» — yumshoq belgi, «твёрдый знак ъ» — qattik belgi. «мать» so''zi ь bilan yoziladi.', '{"pairs":[{"ru":"согласная буква","uz":"undosh harf"},{"ru":"мягкий знак ь","uz":"yumshoq belgi"},{"ru":"твёрдый знак ъ","uz":"qattik belgi"},{"ru":"мать","uz":"ona"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q03', 'a1-m2-l3', 3, 'fill_blank', '«ь» — yumshoq belgi: u undoshni yumshoqtiradi va so''z oxirida turadi (мать, дочь). «ъ» esa qattik belgi.', '{"sentence":"Слова «мать» и «дочь» пишутся с буквой ___.","options":["ъ","о","и","ь"],"correctIndex":3}'::jsonb, 'Слова «мать» и «дочь» пишутся с буквой ___.', array['ъ', 'о', 'и', 'ь'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q04', 'a1-m2-l3', 4, 'multiple_choice', '«ь» undoshni yumshoqtiradi (мать → [м''ать]) va so''z ma''nosini o''zgartirmaydi. So''z bo''g''ini ajratish uchun esa «ъ» ishlatiladi.', '{"prompt":"«Мать» so''zidagi «ь» nima uchun yoziladi?","promptLang":"uz","options":["Undoshni yumshoqtirish uchun","Unlini uzaytirish uchun","Urg''u uchun","So''zni ajratish uchun"],"correctIndex":0}'::jsonb, '«Мать» so''zidagi «ь» nima uchun yoziladi?', array['Undoshni yumshoqtirish uchun', 'Unlini uzaytirish uchun', 'Urg''u uchun', 'So''zni ajratish uchun'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q05', 'a1-m2-l3', 5, 'true_false', 'To''g''ri: «ъ» — твёрдый знак (qattik belgi). U so''z bo''g''ini ajratib turadi, masalan «подъезд».', '{"ruText":"Буква «ъ» — твёрдый знак.","uzTranslation":"«ъ» harfi qattik belgi.","isTrue":true}'::jsonb, 'Буква «ъ» — твёрдый знак.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q06', 'a1-m2-l3', 6, 'true_false', 'Bu noto''g''ri: «ь» ovozni o''zgartirmaydi, uni faqat yumshoqtiradi. Masalan: «мать» — [м''ать], ma''no o''zgarmaydi.', '{"ruText":"Буква «ь» меняет звук полностью.","uzTranslation":"«ь» harfi ovozni butunlay o''zgartiradi.","isTrue":false}'::jsonb, 'Буква «ь» меняет звук полностью.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q07', 'a1-m2-l3', 7, 'listening', '«мать» — ona, «брат» — aka-uka. «мать» so''zida yumshoq belgi «ь» bor, «брат» esa qattik undoshlar bilan tugaydi.', '{"speakText":"Мать и брат.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Ota va ona","Ona va aka-uka","Do''st va dushman","O''qituvchi va talaba"],"correctIndex":1}'::jsonb, 'Мать и брат.', array['Ota va ona', 'Ona va aka-uka', 'Do''st va dushman', 'O''qituvchi va talaba'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q08', 'a1-m2-l3', 8, 'word_selection', '«ъ» — твёрдый знак (qattik belgi), «ь» — мягкий знак (yumshoq belgi). «ё» va «э» esa unli harflar.', '{"promptUz":"Qattik belgi","options":["ь","ё","ъ","э"],"correctIndex":2}'::jsonb, 'Qattik belgi', array['ь', 'ё', 'ъ', 'э'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q09', 'a1-m2-l3', 9, 'sentence_building', '«У меня есть брат и сестра» — «Mening aka-ukam va opa-singlim bor». «есть» — bor (bo''lish fe''li).', '{"correct":["У","меня","есть","брат","и","сестра","."],"distractors":["мать","дом","школа"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q10', 'a1-m2-l3', 10, 'multiple_choice', '«щ» doim yumshoq o''qiladi. «ж» va «ш» doim qattik, «ц» ham doim qattik o''qiladi.', '{"prompt":"Quyidagi qaysi harf doim yumshoq o''qiladi?","promptLang":"uz","options":["ц","ш","щ","ж"],"correctIndex":2}'::jsonb, 'Quyidagi qaysi harf doim yumshoq o''qiladi?', array['ц', 'ш', 'щ', 'ж'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q11', 'a1-m2-l3', 11, 'translation', '«Yumshoq belgi» — «мягкий знак» (ь). U undoshni yumshoqtiradi: мать, дочь, ночь.', '{"direction":"uz_to_ru","source":"Yumshoq belgi","accepted":["мягкий знак"]}'::jsonb, 'Yumshoq belgi', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l3-q12', 'a1-m2-l3', 12, 'fill_blank', '«подъезд» so''zida qattik belgi «ъ» bor: u «под» va «езд» qismlarini ajratib turadi.', '{"sentence":"В слове «подъезд» есть буква ___.","options":["ь","ы","э","ъ"],"correctIndex":3}'::jsonb, 'В слове «подъезд» есть буква ___.', array['ь', 'ы', 'э', 'ъ'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q01', 'a1-m2-l4', 1, 'multiple_choice', '«ч» doim «ch» tovushida o''qiladi: «чай» — choy. Bu o''zbek tilidagi «ch» bilan deyarli bir xil.', '{"prompt":"«чай» so''zidagi «ч» qaysi o''zbekcha tovushga yaqin?","promptLang":"uz","options":["sh (shar)","ch (choy)","j (juk)","ts (tsirk)"],"correctIndex":1}'::jsonb, '«чай» so''zidagi «ч» qaysi o''zbekcha tovushga yaqin?', array['sh (shar)', 'ch (choy)', 'j (juk)', 'ts (tsirk)'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q02', 'a1-m2-l4', 2, 'multiple_choice', '«ж» — «j» tovushiga yaqin: «жук» — juk (kuya). «ш» esa «sh» (shar) kabi o''qiladi.', '{"prompt":"«ж» harfi qaysi o''zbekcha tovushga yaqin?","promptLang":"uz","options":["sh","ch","ts","j"],"correctIndex":3}'::jsonb, '«ж» harfi qaysi o''zbekcha tovushga yaqin?', array['sh', 'ch', 'ts', 'j'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q03', 'a1-m2-l4', 3, 'word_selection', '«чай» — choy; «ч» = ch tovushi. «чашка» — chashka, «шар» — shar, «цех» — sex (boshqa so''zlar).', '{"promptUz":"Choy","options":["шар","чай","цех","чашка"],"correctIndex":1}'::jsonb, 'Choy', array['шар', 'чай', 'цех', 'чашка'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q04', 'a1-m2-l4', 4, 'listening', '«шар» — «sh» tovushi bilan o''qiladi: shar (shinchoq). «чай» esa «ch» (choy) deb o''qiladi.', '{"speakText":"Шар.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Shar (shinchoq)","Choy","Kuya","Tepsi"],"correctIndex":0}'::jsonb, 'Шар.', array['Shar (shinchoq)', 'Choy', 'Kuya', 'Tepsi'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q05', 'a1-m2-l4', 5, 'fill_blank', '«щ» — doim yumshoq «sh''» tovushi: «щи» o''zbekchada «shi» ga yaqin. «ш» esa qattiq «sh» («шар» — shar) bo''ladi.', '{"sentence":"Буква «щ» читается как «___».","options":["ch","ts","j","sh''"],"correctIndex":3}'::jsonb, 'Буква «щ» читается как «___».', array['ch', 'ts', 'j', 'sh'''], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q06', 'a1-m2-l4', 6, 'translation', '«Цирк» — sirk. «ц» harfi «ts» tovushida o''qiladi: tsirk, o''zbek tilida esa «sirk» bo''ladi.', '{"direction":"ru_to_uz","source":"Цирк","accepted":["sirk"]}'::jsonb, 'Цирк', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q07', 'a1-m2-l4', 7, 'true_false', 'To''g''ri: «ж» va «ш» doim qattik o''qiladi, ularning yumshoq jufti yo''q. «ч» va «щ» esa doim yumshoq.', '{"ruText":"Буквы «ж» и «ш» всегда твёрдые.","uzTranslation":"«ж» va «ш» harflari doim qattik o''qiladi.","isTrue":true}'::jsonb, 'Буквы «ж» и «ш» всегда твёрдые.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q08', 'a1-m2-l4', 8, 'true_false', 'Bu noto''g''ri: «ы» og''iz orqasida (o''zbek «ı» ga yaqin), «и» esa tilda oldinda (o''zbek «i» ga yaqin) o''qiladi.', '{"ruText":"Буква «ы» — это то же самое, что «и».","uzTranslation":"«ы» va «и» — bir xil tovush.","isTrue":false}'::jsonb, 'Буква «ы» — это то же самое, что «и».', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q09', 'a1-m2-l4', 9, 'word_matching', '«чай» — choy (ch), «шар» — shinchoq (sh), «жук» — kuya (j), «цирк» — sirk (ts).', '{"pairs":[{"ru":"чай","uz":"choy"},{"ru":"шар","uz":"shinchoq"},{"ru":"жук","uz":"kuya"},{"ru":"цирк","uz":"sirk"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q10', 'a1-m2-l4', 10, 'multiple_choice', '«ы» — og''iz orqasida chiqariladigan unli tovush, o''zbek «ı» ga yaqin. «и» esa tilda oldinda, «i» ga yaqin o''qiladi.', '{"prompt":"«ы» harfi qanday o''qiladi?","promptLang":"uz","options":["Og''iz orqasida (o''zbek «ı» ga yaqin)","Tilda oldinda («i» ga yaqin)","Lab bilan («u» ga yaqin)","Og''iz ochib («a» ga yaqin)"],"correctIndex":0}'::jsonb, '«ы» harfi qanday o''qiladi?', array['Og''iz orqasida (o''zbek «ı» ga yaqin)', 'Tilda oldinda («i» ga yaqin)', 'Lab bilan («u» ga yaqin)', 'Og''iz ochib («a» ga yaqin)'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q11', 'a1-m2-l4', 11, 'sentence_building', '«Она пьёт чай» — «U choy ichmoqda». «пьёт» — ichmoqda (3-shaxs), «чай» — choy.', '{"correct":["Она","пьёт","чай","."],"distractors":["жук","шар","вижу"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l4-q12', 'a1-m2-l4', 12, 'listening', '«Цирк» — «ts» tovushi bilan o''qiladi: tsirk → sirk. «чай» esa «ch» (choy), «шар» esa «sh» (shar) bo''ladi.', '{"speakText":"Цирк.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Choy","Shar","Sirk","Kuya"],"correctIndex":2}'::jsonb, 'Цирк.', array['Choy', 'Shar', 'Sirk', 'Kuya'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q01', 'a1-m2-l5', 1, 'multiple_choice', '«мама» = ма-ма, ya''ni 2 ta bo''g''in. Har bir unli harf yangi bo''g''in boshlaydi.', '{"prompt":"«Мама» so''zi nechta bo''g''inga bo''linadi?","promptLang":"uz","options":["1","3","2","4"],"correctIndex":2}'::jsonb, '«Мама» so''zi nechta bo''g''inga bo''linadi?', array['1', '3', '2', '4'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q02', 'a1-m2-l5', 2, 'fill_blank', '«мама» — ма-ма: ikkala bo''g''inda ham «а» bor. Bo''g''inlar soni unli harflar soniga teng.', '{"sentence":"Слово «мама» состоит из слогов: ма-___.","options":["мо","ме","му","ма"],"correctIndex":3}'::jsonb, 'Слово «мама» состоит из слогов: ма-___.', array['мо', 'ме', 'му', 'ма'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q03', 'a1-m2-l5', 3, 'word_selection', '«дом» — uy; «кот» — mushuk; «брат» — aka-uka; «школа» — maktab.', '{"promptUz":"Uy","options":["дом","кот","брат","школа"],"correctIndex":0}'::jsonb, 'Uy', array['дом', 'кот', 'брат', 'школа'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q04', 'a1-m2-l5', 4, 'translation', '«брат» — aka-uka, «сестра» — opa-singil. «и» — va (ulash so''zi), shuning uchun ikkala so''z birlashadi.', '{"direction":"ru_to_uz","source":"Брат и сестра.","accepted":["aka-uka va opa-singil","aka va opa-singil"]}'::jsonb, 'Брат и сестра.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q05', 'a1-m2-l5', 5, 'listening', '«мама» — ona, «папа» — ota. Bu so''zlar bo''g''inlarga ajratib o''qiladi: ма-ма, па-па.', '{"speakText":"Мама и папа.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Aka va opa","O''qituvchi va talaba","Ona va ota","Uy va maktab"],"correctIndex":2}'::jsonb, 'Мама и папа.', array['Aka va opa', 'O''qituvchi va talaba', 'Ona va ota', 'Uy va maktab'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q06', 'a1-m2-l5', 6, 'true_false', 'To''g''ri: «школа» ikki bo''g''inga bo''linadi — шко-ла. Birinchi bo''g''inning oxirida unli «о» turadi.', '{"ruText":"Слово «школа» читается как шко-ла.","uzTranslation":"«школа» so''zi «шко-ла» deb o''qiladi.","isTrue":true}'::jsonb, 'Слово «школа» читается как шко-ла.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q07', 'a1-m2-l5', 7, 'sentence_building', '«Это мой брат» — «Bu menim aka-ukam». «мой» — menim (erkak jins uchun), «моя» — menim (ayol jins uchun).', '{"correct":["Это","мой","брат","."],"distractors":["сестра","есть","большой"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q08', 'a1-m2-l5', 8, 'multiple_choice', '«учитель» = у-чи-тель, ya''ni 3 ta bo''g''in. Har bir unli harf (у, и, е) yangi bo''g''in boshlaydi.', '{"prompt":"«Учитель» so''zi nechta bo''g''inga bo''linadi?","promptLang":"uz","options":["4","2","5","3"],"correctIndex":3}'::jsonb, '«Учитель» so''zi nechta bo''g''inga bo''linadi?', array['4', '2', '5', '3'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q09', 'a1-m2-l5', 9, 'fill_blank', '«школа» = шко-ла: birinchi bo''g''in — «шко», ikkinchisi — «ла». Bo''g''inlar unli harflarga qarab ajraladi.', '{"sentence":"Первый слог в слове «школа»: ___.","options":["шко","ло","ша","ко"],"correctIndex":0}'::jsonb, 'Первый слог в слове «школа»: ___.', array['шко', 'ло', 'ша', 'ко'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q10', 'a1-m2-l5', 10, 'word_matching', '«мама» — ona, «папа» — ota, «дом» — uy, «школа» — maktab. Bu so''zlarni bo''g''inlarga ajratib o''qing.', '{"pairs":[{"ru":"мама","uz":"ona"},{"ru":"папа","uz":"ota"},{"ru":"дом","uz":"uy"},{"ru":"школа","uz":"maktab"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q11', 'a1-m2-l5', 11, 'translation', '«Bu menim aka-ukam» — «Это мой брат». «брат» — aka-uka, «сестра» — opa-singil.', '{"direction":"uz_to_ru","source":"Bu menim aka-ukam.","accepted":["это мой брат","это мой брат?"]}'::jsonb, 'Bu menim aka-ukam.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m2-l5-q12', 'a1-m2-l5', 12, 'true_false', 'To''g''ri: с-е-с-т-р-а — 6 ta harf, «с» so''zda ikki marta takrorlanadi.', '{"ruText":"Слово «сестра» состоит из шести букв.","uzTranslation":"«сестра» so''zi olti harfdan iborat.","isTrue":true}'::jsonb, 'Слово «сестра» состоит из шести букв.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q01', 'a1-m3-l1', 1, 'word_selection', '«Сестра» — opa yoki singil. «брат» esa aka yoki ukadir, o''zbekchada ikkalasi ham uchalik bo''ladi.', '{"promptUz":"Singil (opa)","options":["сестра","брат","мама","дочка"],"correctIndex":0}'::jsonb, 'Singil (opa)', array['сестра', 'брат', 'мама', 'дочка'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q02', 'a1-m3-l1', 2, 'translation', '«Бабушка» — buvimona (ota-onamizning onasi). «Моя» kichik harfli yoziladi va «mening» degan ma''noni beradi.', '{"direction":"ru_to_uz","source":"Моя бабушка.","accepted":["mening buvimomam","buvimomam","mening buvimona"]}'::jsonb, 'Моя бабушка.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q03', 'a1-m3-l1', 3, 'multiple_choice', '«Папа» — dada yoki ota. «Мама» — ona, «брат» — aka/uka, «сестра» — opa/singil.', '{"prompt":"«Папа» so''zi nima degani?","promptLang":"uz","options":["Ota (dada)","Aka","O''g''il","Singil"],"correctIndex":0}'::jsonb, '«Папа» so''zi nima degani?', array['Ota (dada)', 'Aka', 'O''g''il', 'Singil'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q04', 'a1-m3-l1', 4, 'word_matching', 'Asosiy oila a''zolari: мама — ona, папа — dada, брат — aka/uka, сестра — opa/singil.', '{"pairs":[{"ru":"Мама","uz":"Ona"},{"ru":"Папа","uz":"Dada"},{"ru":"Брат","uz":"Aka"},{"ru":"Сестра","uz":"Opa"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q05', 'a1-m3-l1', 5, 'listening', '«Это моя сестра» — «Bu menim singlim (opam)». «сестра» ayol jinsli bo''lgani uchun «моя» ishlatiladi.', '{"speakText":"Это моя сестра.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Bu menim ukam","Bu menim qizim","Bu menim buvim","Bu menim singlim"],"correctIndex":3}'::jsonb, 'Это моя сестра.', array['Bu menim ukam', 'Bu menim qizim', 'Bu menim buvim', 'Bu menim singlim'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q06', 'a1-m3-l1', 6, 'fill_blank', '«брат» — erkak jinsli ot, shuning uchun unga «мой» (menim) olmoshi mos keladi. «сестра» uchun «моя» bo''lardi.', '{"sentence":"Это мой ___.","options":["сестра","мама","брат","бабушка"],"correctIndex":2}'::jsonb, 'Это мой ___.', array['сестра', 'мама', 'брат', 'бабушка'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q07', 'a1-m3-l1', 7, 'sentence_building', '«Это моя мама» — «Bu menim onam». «мама» ayol jinsli bo''lgani uchun «моя» olmoshi olinadi.', '{"correct":["Это","моя","мама","."],"distractors":["папа","мой","брат"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q08', 'a1-m3-l1', 8, 'translation', '«Bu menim ukam» — «Это мой брат». «мой» (menim) erkak jinsli «брат» so''ziga mos keladi.', '{"direction":"uz_to_ru","source":"Bu menim ukam.","accepted":["это мой брат","мой брат","это мой брат?"]}'::jsonb, 'Bu menim ukam.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q09', 'a1-m3-l1', 9, 'true_false', '«У меня есть...» — «Mening ... bor» degan tayyor ibora, u egallik (meniki) bildiradi.', '{"ruText":"У меня есть брат и сестра.","uzTranslation":"Mening ukam va singlim bor.","isTrue":true}'::jsonb, 'У меня есть брат и сестра.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q10', 'a1-m3-l1', 10, 'multiple_choice', '«Дедушка» — buvimoza (katta otamiz), «бабушка» — buvimona. Bu ikkita so''zni adashtirmang.', '{"prompt":"«Дедушка» — bu kim?","promptLang":"uz","options":["Buvimona","Buvimoza","Ona","O''g''il"],"correctIndex":1}'::jsonb, '«Дедушка» — bu kim?', array['Buvimona', 'Buvimoza', 'Ona', 'O''g''il'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q11', 'a1-m3-l1', 11, 'word_selection', '«Дочка» — qizim (o''z qizimiz). «Сын» — o''g''lim, «жена» — turmush o''roq (ayol).', '{"promptUz":"Qizim","options":["сын","дочка","сестра","жена"],"correctIndex":1}'::jsonb, 'Qizim', array['сын', 'дочка', 'сестра', 'жена'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l1-q12', 'a1-m3-l1', 12, 'true_false', '«Дедушка» — buvimoza, ya''ni buvayoning eri. U «брат» (aka/uka) yoki «сестра» (singil) emas.', '{"ruText":"Дедушка — это отец папы.","uzTranslation":"Buvimoza — dadamning akasi.","isTrue":false}'::jsonb, 'Дедушка — это отец папы.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q01', 'a1-m3-l2', 1, 'multiple_choice', '«В моей семье пять человек» — «Mening oilamda besh kishi». «человек» bu yerda son bilan birga «kishi» degan ma''noni beradi.', '{"prompt":"«В моей семье пять человек» ning to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Mening oilamda besh yosh","Mening oilamda besh kishi","Besh kishi meni kutmoqda","Mening oilam beshinchi"],"correctIndex":1}'::jsonb, '«В моей семье пять человек» ning to''g''ri tarjimasini tanlang.', array['Mening oilamda besh yosh', 'Mening oilamda besh kishi', 'Besh kishi meni kutmoqda', 'Mening oilam beshinchi'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q02', 'a1-m3-l2', 2, 'fill_blank', 'Sonlardan keyin «человек» doim oddiy shaklda turadi: «пять человек» (besh kishi). Boshqa shakllar bu yerda ishlatilmaydi.', '{"sentence":"В моей семье ___ человек.","options":["пять","пяти","пятью","пятые"],"correctIndex":0}'::jsonb, 'В моей семье ___ человек.', array['пять', 'пяти', 'пятью', 'пятые'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q03', 'a1-m3-l2', 3, 'translation', '«У меня есть...» — «...bor» degan tayyor ibora. «два брата» — «ikki ukam»: rus tilida «два» dan keyin ot ko''maklashuv shaklida turadi.', '{"direction":"ru_to_uz","source":"У меня есть два брата.","accepted":["mening ikki ukam bor","ikka ukam bor","mening 2 ukam bor","ikki ukam bor"]}'::jsonb, 'У меня есть два брата.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q04', 'a1-m3-l2', 4, 'word_matching', 'Oila haqida gapirish iboralari: «У меня есть...» — ... bor, «В моей семье» — Mening oilamda, «Моя мама» — Mening onam, «Нас пятеро» — Biz beshmiz.', '{"pairs":[{"ru":"У меня есть брат","uz":"Mening ukam bor"},{"ru":"В моей семье","uz":"Mening oilamda"},{"ru":"Моя мама","uz":"Mening onam"},{"ru":"Нас пятеро","uz":"Biz beshmiz"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q05', 'a1-m3-l2', 5, 'listening', '«четыре» — to''rt, «человек» — kishi. «В моей семье четыре человека» — «Mening oilamda to''rt kishi».', '{"speakText":"В моей семье четыре человека.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Mening oilamda besh kishi","Mening oilamda besh yosh","Mening oilamda olti kishi","Mening oilamda to''rt kishi"],"correctIndex":3}'::jsonb, 'В моей семье четыре человека.', array['Mening oilamda besh kishi', 'Mening oilamda besh yosh', 'Mening oilamda olti kishi', 'Mening oilamda to''rt kishi'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q06', 'a1-m3-l2', 6, 'sentence_building', '«В моей семье пять человек» — «Mening oilamda besh kishi». «моей» — «моя» so''zining kelishik shakli («в» dan keyin).', '{"correct":["В","моей","семье","пять","человек","."],"distractors":["моя","три","дома"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q07', 'a1-m3-l2', 7, 'word_selection', '«Моя семья» — mening oilam. «семья» ayol jinsli bo''lgani uchun «моя» olmoshi olinadi.', '{"promptUz":"Mening oilam","options":["твоя семья","моя семья","их семья","наша семья"],"correctIndex":1}'::jsonb, 'Mening oilam', array['твоя семья', 'моя семья', 'их семья', 'наша семья'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q08', 'a1-m3-l2', 8, 'multiple_choice', '«учительница» — ayol o''qituvchi. «Моя мама — учительница» — «Mening onam o''qituvchi».', '{"prompt":"«Моя мама — учительница» degan gap ma''nosi qaysi?","promptLang":"uz","options":["Mening onam o''qituvchi","Mening opam talaba","Mening dadam o''qituvchi","Mening singlim o''qituvchi"],"correctIndex":0}'::jsonb, '«Моя мама — учительница» degan gap ma''nosi qaysi?', array['Mening onam o''qituvchi', 'Mening opam talaba', 'Mening dadam o''qituvchi', 'Mening singlim o''qituvchi'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q09', 'a1-m3-l2', 9, 'true_false', '«три» — uch, «шесть» — olti. Tarjimadagi son gapdagi songa mos kelmagani uchun noto''g''ri.', '{"ruText":"В моей семье три человека.","uzTranslation":"Mening oilamda olti kishi bor.","isTrue":false}'::jsonb, 'В моей семье три человека.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q10', 'a1-m3-l2', 10, 'translation', '«Mening oilamda ... kishi bor» — «В моей семье ... человек». «bor» bu yerda «человек» bilan ifodalanadi.', '{"direction":"uz_to_ru","source":"Mening oilamda besh kishi bor.","accepted":["в моей семье пять человек","в нашей семье пять человек","в моей семье пять человек?"]}'::jsonb, 'Mening oilamda besh kishi bor.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l2-q11', 'a1-m3-l2', 11, 'fill_blank', '«учительница» — ayol o''qituvchi, «учитель» — erkak o''qituvchi. «мама» ayol bo''lgani uchun jins moslashuviga e''tibor bering.', '{"sentence":"Моя мама — ___.","options":["учительницы","учитель","ученица","учительница"],"correctIndex":3}'::jsonb, 'Моя мама — ___.', array['учительницы', 'учитель', 'ученица', 'учительница'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q01', 'a1-m3-l3', 1, 'multiple_choice', '«mening» — «мой» (erkak), «моя» (ayol), «моё» (neitr), «мои» (ko''plik). Olmosh formasi ot jinsiga qarab tanlanadi.', '{"prompt":"«Mening» so''ziga mos rus egalik olmoshi qaysi?","promptLang":"uz","options":["мой / моя / моё / мои","твой / твоя / твоё","его / её","наш / ваш"],"correctIndex":0}'::jsonb, '«Mening» so''ziga mos rus egalik olmoshi qaysi?', array['мой / моя / моё / мои', 'твой / твоя / твоё', 'его / её', 'наш / ваш'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q02', 'a1-m3-l3', 2, 'fill_blank', '«сестра» — ayol jinsli ot, uchun «моя» olmoshi olinadi. «мой» erkak (брат), «моё» neitr (окно) uchun.', '{"sentence":"Это ___ сестра.","options":["мой","моё","мои","моя"],"correctIndex":3}'::jsonb, 'Это ___ сестра.', array['мой', 'моё', 'мои', 'моя'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q03', 'a1-m3-l3', 3, 'fill_blank', '«брат» — erkak jinsli ot, uchun «мой» (menim) ishlatiladi: «Это мой брат». «моя» ayol jins uchun.', '{"sentence":"Это ___ брат.","options":["моя","моё","мой","наши"],"correctIndex":2}'::jsonb, 'Это ___ брат.', array['моя', 'моё', 'мой', 'наши'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q04', 'a1-m3-l3', 4, 'translation', '«окно» — deraza va neitr jinsli; shuning uchun unga «моё» (menim) olmoshi olinadi.', '{"direction":"ru_to_uz","source":"Это моё окно.","accepted":["bu menim derazam","mening derazam","bu menim deraza"]}'::jsonb, 'Это моё окно.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q05', 'a1-m3-l3', 5, 'word_matching', 'Egalik olmoshlari: «мой» — menim, «твой» — sening, «наш» — bizning, «их» — ularning (ko''plik egasi).', '{"pairs":[{"ru":"мой","uz":"menim"},{"ru":"твой","uz":"sening"},{"ru":"наш","uz":"bizning"},{"ru":"их","uz":"ularning"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q06', 'a1-m3-l3', 6, 'word_selection', '«твой» — sening (2-shaxs). «мой» — menim, «наш» — bizning, «его» — uning (erkak).', '{"promptUz":"Sening","options":["мой","твой","наш","его"],"correctIndex":1}'::jsonb, 'Sening', array['мой', 'твой', 'наш', 'его'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q07', 'a1-m3-l3', 7, 'listening', '«её» — uning (ayol shaxs nikidagi olmosh), «мама» — ona. «Это её мама» — «Bu uning onasi».', '{"speakText":"Это её мама.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Bu uning opasi","Bu uning qizi","Bu uning buvisi","Bu uning onasi"],"correctIndex":3}'::jsonb, 'Это её мама.', array['Bu uning opasi', 'Bu uning qizi', 'Bu uning buvisi', 'Bu uning onasi'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q08', 'a1-m3-l3', 8, 'sentence_building', '«Это наш дом» — «Bu bizning uyingiz». «наш» — bizning; ko''plik shakli «наши» bo''ladi.', '{"correct":["Это","наш","дом","."],"distractors":["мой","её","книга"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q09', 'a1-m3-l3', 9, 'multiple_choice', '«его» — uning (erkak: брат, папа), «её» — uning (ayol: мама, сестра). O''zbekchada ikkalasi ham «uning» bo''ladi.', '{"prompt":"«его» va «её» farqi nimada?","promptLang":"uz","options":["Иkkalasi bir xil","«его» ko''plik uchun","«её» erkak uchun","«его» — erkak uchun, «её» — ayol uchun"],"correctIndex":3}'::jsonb, '«его» va «её» farqi nimada?', array['Иkkalasi bir xil', '«его» ko''plik uchun', '«её» erkak uchun', '«его» — erkak uchun, «её» — ayol uchun'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q10', 'a1-m3-l3', 10, 'translation', '«sizning» — «ваш». «книга» ayol jinsli bo''lgani uchun «ваша» shakli olinadi: «это ваша книга».', '{"direction":"uz_to_ru","source":"Bu sizning kitobingiz.","accepted":["это ваша книга","ваша книга","это ваша книга?"]}'::jsonb, 'Bu sizning kitobingiz.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q11', 'a1-m3-l3', 11, 'true_false', '«их» — ularning (ko''plik egasi). «семья» — oila va ayol jinsli ot, tarjima to''g''ri.', '{"ruText":"Это их семья.","uzTranslation":"Bu ularning oilasi.","isTrue":true}'::jsonb, 'Это их семья.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l3-q12', 'a1-m3-l3', 12, 'true_false', '«твоя» — sening (2-shaxs), «моя» — menim (1-shaxs). Tarjimada 1-shaxs olmoshi ishlatilgani uchun noto''g''ri.', '{"ruText":"Это твоя комната.","uzTranslation":"Bu mening xonam.","isTrue":false}'::jsonb, 'Это твоя комната.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q01', 'a1-m3-l4', 1, 'sentence_building', '«У меня есть брат» — «Mening ukam bor». «есть» (bor) rus tilida mavjudlikni bildiradi.', '{"correct":["У","меня","есть","брат","."],"distractors":["нет","сестра","вы"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q02', 'a1-m3-l4', 2, 'fill_blank', '«У меня есть...» — tayyor ibora («mening ... bor»). «имеет» bu yerda ishlatilmaydi, u faqat uchinchi shaxsda turadi.', '{"sentence":"У меня ___ сестра.","options":["есть","имеет","имя","был"],"correctIndex":0}'::jsonb, 'У меня ___ сестра.', array['есть', 'имеет', 'имя', 'был'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q03', 'a1-m3-l4', 3, 'translation', '«живёт» — yashaydi, «в Ташкенте» — Toshkentda. Gap tartibi: egalik olmoshi + ot + fe''l.', '{"direction":"ru_to_uz","source":"Моя сестра живёт в Ташкенте.","accepted":["mening singlim toshkentda yashaydi","singlim toshkentda yashaydi","mening opam toshkentda yashaydi"]}'::jsonb, 'Моя сестра живёт в Ташкенте.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q04', 'a1-m3-l4', 4, 'multiple_choice', '«мама» — ayol jinsli ot, uchun «моя» olmoshi olinadi: «Это моя мама». «мой» va «моё» bu yerda noto''g''ri.', '{"prompt":"Qaysi gap to''g''ri yozilgan?","promptLang":"uz","options":["Это моё мама","Это моя мама","Это мой мама","Это мои мама"],"correctIndex":1}'::jsonb, 'Qaysi gap to''g''ri yozilgan?', array['Это моё мама', 'Это моя мама', 'Это мой мама', 'Это мои мама'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q05', 'a1-m3-l4', 5, 'listening', '«Мой папа — врач» — «Menim dadam shifokor». «врач» — shifokor kasbi, «учитель» — o''qituvchi kasbi.', '{"speakText":"Мой папа — врач.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Menim dadam shifokor","Menim dadam o''qituvchi","Menim ukam shifokor","Menim onam talaba"],"correctIndex":0}'::jsonb, 'Мой папа — врач.', array['Menim dadam shifokor', 'Menim dadam o''qituvchi', 'Menim ukam shifokor', 'Menim onam talaba'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q06', 'a1-m3-l4', 6, 'word_selection', '«есть» (bor) mavjudlikni bildiradi: «У меня есть брат». «нет» — yo''q, «был» — bo''lgan.', '{"promptUz":"Mening ukam bor","options":["нет","есть","был","будет"],"correctIndex":1}'::jsonb, 'Mening ukam bor', array['нет', 'есть', 'был', 'будет'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q07', 'a1-m3-l4', 7, 'word_matching', 'Gap elementlari: «В моей семье» — Mening oilamda, «Моя сестра» — Mening singlim, «живёт» — yashaydi, «работает» — ishlaydi.', '{"pairs":[{"ru":"В моей семье","uz":"Mening oilamda"},{"ru":"Моя сестра","uz":"Mening singlim"},{"ru":"живёт","uz":"yashaydi"},{"ru":"работает","uz":"ishlaydi"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q08', 'a1-m3-l4', 8, 'translation', '«Mening oilamda ... kishi bor» — «В моей семье ... человек». «шесть» — olti, «человек» sonlardan keyin ham bir xil qoladi.', '{"direction":"uz_to_ru","source":"Mening oilamda olti kishi bor.","accepted":["в моей семье шесть человек","в нашей семье шесть человек","в моей семье шесть человек?"]}'::jsonb, 'Mening oilamda olti kishi bor.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q09', 'a1-m3-l4', 9, 'true_false', '«учится в школе» — maktabda o''qiydi. «учиться» fe''li uchinchi shaxs birlikda «учится» bo''ladi.', '{"ruText":"Мой брат учится в школе.","uzTranslation":"Mening ukam maktabda o''qiydi.","isTrue":true}'::jsonb, 'Мой брат учится в школе.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q10', 'a1-m3-l4', 10, 'fill_blank', '«учится» — o''qimoq (3-shaxs, birlik): «Моя сестра учится в школе». «учит» esa «o''rgatadi» degan boshqa ma''noni beradi.', '{"sentence":"Моя сестра ___ в школе.","options":["учит","учим","учат","учится"],"correctIndex":3}'::jsonb, 'Моя сестра ___ в школе.', array['учит', 'учим', 'учат', 'учится'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l4-q11', 'a1-m3-l4', 11, 'multiple_choice', '«нет» — yo''q; u dan keyin ot ko''maklashuv shaklida turadi: «нет сестры» — «singlim yo''q».', '{"prompt":"«В моей семье нет сестры» ning to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Mening oilamda singlim bor","Mening opam katta","Mening oilamda singlim yo''q","Oilmam juda kichik"],"correctIndex":2}'::jsonb, '«В моей семье нет сестры» ning to''g''ri tarjimasini tanlang.', array['Mening oilamda singlim bor', 'Mening opam katta', 'Mening oilamda singlim yo''q', 'Oilmam juda kichik'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q01', 'a1-m3-l5', 1, 'multiple_choice', '«пять» — besh. Oila a''zolari: папа, мама, брат, сестра va suhbatdoshning o''zi — jami besh kishi.', '{"prompt":"— У тебя большая семья? — Да, в моей семье пять человек: папа, мама, брат, сестра и я. Oilada nechta kishi bor?","promptLang":"uz","options":["To''rt","Besh","Olti","Uch"],"correctIndex":1}'::jsonb, '— У тебя большая семья? — Да, в моей семье пять человек: папа, мама, брат, сестра и я. Oilada nechta kishi bor?', array['To''rt', 'Besh', 'Olti', 'Uch'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q02', 'a1-m3-l5', 2, 'fill_blank', '«Сколько вас в семье?» — oilada nechtasizlar? Javobda son oddiy shaklda turadi: «пять человек».', '{"sentence":"— Сколько вас в семье? — В моей семье ___ человек.","options":["пять","пяти","пятью","пятый"],"correctIndex":0}'::jsonb, '— Сколько вас в семье? — В моей семье ___ человек.', array['пять', 'пяти', 'пятью', 'пятый'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q03', 'a1-m3-l5', 3, 'translation', '«Мой папа — врач» — «Menim dadam shifokor». «—» belgisi «bu ...» degan ma''noni bildiradi (ravish).', '{"direction":"ru_to_uz","source":"Мой папа — врач.","accepted":["mening dadam shifokor","mening otam shifokor","dadam shifokor"]}'::jsonb, 'Мой папа — врач.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q04', 'a1-m3-l5', 4, 'listening', '«пять человек» — besh kishi. Bu yerda «лет» (yosh) emas, «человек» (kishi) ishlatiladi.', '{"speakText":"В моей семье пять человек.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Mening oilamda besh yosh","Mening ukam besh yoshda","Mening oilamda besh kishi","Besh kishi kelmoqda"],"correctIndex":2}'::jsonb, 'В моей семье пять человек.', array['Mening oilamda besh yosh', 'Mening ukam besh yoshda', 'Mening oilamda besh kishi', 'Besh kishi kelmoqda'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q05', 'a1-m3-l5', 5, 'word_matching', '«родители» — ota-onalar, «врач» — shifokor, «учительница» — ayol o''qituvchi, «студент» — talaba.', '{"pairs":[{"ru":"родители","uz":"Ota-onalar"},{"ru":"врач","uz":"Shifokor"},{"ru":"учительница","uz":"O''qituvchi"},{"ru":"студент","uz":"Talaba"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q06', 'a1-m3-l5', 6, 'sentence_building', '«Моя мама — учительница» — «Mening onam o''qituvchi». Ravish (—) alohida belgi sifatida qo''yiladi.', '{"correct":["Моя","мама","—","учительница","."],"distractors":["папа","врач","мой"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q07', 'a1-m3-l5', 7, 'true_false', '«старше» — kattaroq («старый» so''zining taqqoslash darajasi), «студент» — talaba. Tarjima to''g''ri.', '{"ruText":"Брат старше, он студент.","uzTranslation":"Ukam kattaroq, u talaba.","isTrue":true}'::jsonb, 'Брат старше, он студент.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q08', 'a1-m3-l5', 8, 'word_selection', '«Родители» — ota-onalar (ota va ona birgalikda). «родственники» — qarindoshlar, «родина» — Vatan.', '{"promptUz":"Ota-onalar","options":["родственники","родина","родители","родной"],"correctIndex":2}'::jsonb, 'Ota-onalar', array['родственники', 'родина', 'родители', 'родной'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q09', 'a1-m3-l5', 9, 'translation', '«Sening oilang kattami?» — «У тебя большая семья?». «большой» — katta, savol gapida oxirida «?» qo''yiladi.', '{"direction":"uz_to_ru","source":"Sening oilang kattami?","accepted":["у тебя большая семья","у тебя большая семья?","у вас большая семья"]}'::jsonb, 'Sening oilang kattami?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q10', 'a1-m3-l5', 10, 'true_false', '«учитель» — o''qituvchi, «студент» — talaba. So''zlar turlicha bo''lgani uchun tarjima noto''g''ri.', '{"ruText":"Мой папа — учитель.","uzTranslation":"Mening dadam talaba.","isTrue":false}'::jsonb, 'Мой папа — учитель.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m3-l5-q11', 'a1-m3-l5', 11, 'multiple_choice', '«врач» — shifokor, bu papaning kasbi. Onaning kasbi esa «учительница» (o''qituvchi).', '{"prompt":"— Мой папа — врач, а моя мама — учительница. Dialogga ko''ra kim shifokor?","promptLang":"uz","options":["Ona","Singil","Ota","Aka"],"correctIndex":2}'::jsonb, '— Мой папа — врач, а моя мама — учительница. Dialogga ko''ra kim shifokor?', array['Ona', 'Singil', 'Ota', 'Aka'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q01', 'a1-m4-l1', 1, 'multiple_choice', '«Тетрадь» — daftar. Maktabda har bir fan uchun alohida tetradan foydalaniladi.', '{"prompt":"«Тетрадь» so''zining to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Kitob","Daftar","Ruchka","Sumka"],"correctIndex":1}'::jsonb, '«Тетрадь» so''zining to''g''ri tarjimasini tanlang.', array['Kitob', 'Daftar', 'Ruchka', 'Sumka'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q02', 'a1-m4-l1', 2, 'translation', '«Карандаш» — karandash. «Кара» qismi «qora» degan ma''noni bildiradi, chunki karandash qora chizadi.', '{"direction":"ru_to_uz","source":"Карандаш","accepted":["karandash"]}'::jsonb, 'Карандаш', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q03', 'a1-m4-l1', 3, 'listening', '«Это ручка.» — «Bu ruchka (qalam)». «Ручка» — ruchka, yozish uchun asosiy maktab buyumi.', '{"speakText":"Это ручка.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Bu daftar.","Bu ruchka.","Bu kitob.","Bu sumka."],"correctIndex":1}'::jsonb, 'Это ручка.', array['Bu daftar.', 'Bu ruchka.', 'Bu kitob.', 'Bu sumka.'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q04', 'a1-m4-l1', 4, 'word_selection', '«Тетрадь» — daftar. «Книга» — kitob, «доска» — dosha, «линейка» — chizg''ich.', '{"promptUz":"Daftar","options":["книга","доска","тетрадь","резинка"],"correctIndex":2}'::jsonb, 'Daftar', array['книга', 'доска', 'тетрадь', 'резинка'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q05', 'a1-m4-l1', 5, 'true_false', '«Линейка» — chizg''ich: u maktab buyumlaridan biri, shuning uchun tarjima to''g''ri.', '{"ruText":"Линейка — это школьная принадлежность.","uzTranslation":"Lineyka — bu maktab buyumi.","isTrue":true}'::jsonb, 'Линейка — это школьная принадлежность.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q06', 'a1-m4-l1', 6, 'sentence_building', '«Это моя тетрадь.» — «Bu menim daftarim». «моя» (menim) ayol jinsidagi ot qoshida turadi: тетрадь — ayol jinsida.', '{"correct":["Это","моя","тетрадь","."],"distractors":["учитель","линейка","сумка"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q07', 'a1-m4-l1', 7, 'fill_blank', '«Писать на доске» — «dosha ustida yozmoq». «на» + joy → predlogniy (joylashuv) padişa: «на доске».', '{"sentence":"Учитель пишет на ___.","options":["доска","доску","доске","доской"],"correctIndex":2}'::jsonb, 'Учитель пишет на ___.', array['доска', 'доску', 'доске', 'доской'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q08', 'a1-m4-l1', 8, 'multiple_choice', '«Резинка» — kauchuk: u ruchka bilan yozilgan xatoni o''chirish uchun ishlatiladi.', '{"prompt":"«Резинка» nimani bildiradi?","promptLang":"uz","options":["Qalam","Daftar","Kauchuk (yozuvni o''chirish)","Chizg''ich"],"correctIndex":2}'::jsonb, '«Резинка» nimani bildiradi?', array['Qalam', 'Daftar', 'Kauchuk (yozuvni o''chirish)', 'Chizg''ich'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q09', 'a1-m4-l1', 9, 'translation', '«Maktab sumkasi» — «школьная сумка». «школьная» — maktabga tegishli sifat (ot + -ная).', '{"direction":"uz_to_ru","source":"Maktab sumkasi","accepted":["школьная сумка","сумка"]}'::jsonb, 'Maktab sumkasi', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q10', 'a1-m4-l1', 10, 'word_matching', 'Maktab buyumlari: тетрадь — daftar, карандаш — karandash, линейка — chizg''ich, резинка — kauchuk.', '{"pairs":[{"ru":"Тетрадь","uz":"Daftar"},{"ru":"Карандаш","uz":"Karandash"},{"ru":"Линейка","uz":"Chizg''ich"},{"ru":"Резинка","uz":"Kauchuk"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q11', 'a1-m4-l1', 11, 'listening', '«Где моя тетрадь?» — «Mening daftarim qayerda?». «где» — qayerda (joy so''rovi).', '{"speakText":"Где моя тетрадь?","promptUz":"Esiting va to''g''ri savolni tanlang.","options":["Mening kitobim qayerda?","Mening ruchkam qayerda?","Mening sumkam qayerda?","Mening daftarim qayerda?"],"correctIndex":3}'::jsonb, 'Где моя тетрадь?', array['Mening kitobim qayerda?', 'Mening ruchkam qayerda?', 'Mening sumkam qayerda?', 'Mening daftarim qayerda?'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l1-q12', 'a1-m4-l1', 12, 'true_false', '«Мел» — doshaga yozish uchun kichik oq toshcha, kitob emas. Shuning uchun tarjima noto''g''ri.', '{"ruText":"Мел — это школьная принадлежность.","uzTranslation":"Mel — bu kitob.","isTrue":false}'::jsonb, 'Мел — это школьная принадлежность.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q01', 'a1-m4-l2', 1, 'word_selection', '«Математика» — matematika. Bu fan raqamlar, tenglamalar va hisoblash bilan bog''liq.', '{"promptUz":"Matematika","options":["география","математика","музыка","химия"],"correctIndex":1}'::jsonb, 'Matematika', array['география', 'математика', 'музыка', 'химия'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q02', 'a1-m4-l2', 2, 'translation', '«История» — tarix (fan nomi). «История» so''zi o''zbekchaga ham xuddi shunday o''xshaydi.', '{"direction":"ru_to_uz","source":"История","accepted":["tarix","tarix fani"]}'::jsonb, 'История', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q03', 'a1-m4-l2', 3, 'multiple_choice', '«Физкультура» — jismoniy tarbiya darsi. «физика» (fizika) bilan adashtirmang: ular boshqa fanlar.', '{"prompt":"«Физкультура» — bu qaysi fan?","promptLang":"uz","options":["Kimyo","Jismoniy tarbiya","Biologiya","Musiqa"],"correctIndex":1}'::jsonb, '«Физкультура» — bu qaysi fan?', array['Kimyo', 'Jismoniy tarbiya', 'Biologiya', 'Musiqa'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q04', 'a1-m4-l2', 4, 'listening', '«У нас сегодня урок географии» — «Bugun bizda geografiya darsi bor». «урок географии» — geografiya darsi (родительный падеж).', '{"speakText":"У нас сегодня урок географии.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Bugun bizda tarix darsi bor.","Ertaga bizda geografiya darsi bor.","Bugun bizda geografiya darsi bor.","Bugun bizda kimyo darsi bor."],"correctIndex":2}'::jsonb, 'У нас сегодня урок географии.', array['Bugun bizda tarix darsi bor.', 'Ertaga bizda geografiya darsi bor.', 'Bugun bizda geografiya darsi bor.', 'Bugun bizda kimyo darsi bor.'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q05', 'a1-m4-l2', 5, 'fill_blank', '«урок музыки» — musiqa darsi. «урок» so''zidan keyin ot roditelniy (egenlik) padişasida turadi: музыки.', '{"sentence":"Я люблю урок ___.","options":["музыка","музыку","музыки","музыкой"],"correctIndex":2}'::jsonb, 'Я люблю урок ___.', array['музыка', 'музыку', 'музыки', 'музыкой'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q06', 'a1-m4-l2', 6, 'sentence_building', '«Я люблю урок математики.» — «Men matematika darsini yaxshi ko''raman». «урок» dan keyin fan nomi egenlik padişasida: математики.', '{"correct":["Я","люблю","урок","математики","."],"distractors":["не","сумка","учитель"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q07', 'a1-m4-l2', 7, 'translation', '«Bugun kimyo darsi bor» — «Сегодня урок химии». «химии» — «химия» so''zining egenlik shakli.', '{"direction":"uz_to_ru","source":"Bugun kimyo darsi bor.","accepted":["сегодня урок химии","сегодня урок химии?"]}'::jsonb, 'Bugun kimyo darsi bor.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q08', 'a1-m4-l2', 8, 'true_false', '«На уроке музыки мы поём» — «Musiqa darsida kuylaymiz». Musiqa darsida qo''shiq aytishadi, tarjima to''g''ri.', '{"ruText":"На уроке музыки мы поём.","uzTranslation":"Musiqa darsida kuylaymiz.","isTrue":true}'::jsonb, 'На уроке музыки мы поём.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q09', 'a1-m4-l2', 9, 'word_matching', 'Fan nomlari: «русский язык» — rus tili, «биология» — biologiya, «химия» — kimyo, «физкультура» — jismoniy tarbiya.', '{"pairs":[{"ru":"Русский язык","uz":"Rus tili"},{"ru":"Биология","uz":"Biologiya"},{"ru":"Химия","uz":"Kimyo"},{"ru":"Физкультура","uz":"Jismoniy tarbiya"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q10', 'a1-m4-l2', 10, 'multiple_choice', '«Английский язык» — ingliz tili. «английский» — Angliyaga tegishli sifat, bu yerda til nomini bildiradi.', '{"prompt":"«Английский язык» nima degani?","promptLang":"uz","options":["Ingliz tili","Fransuz tili","Nemis tili","Rus tili"],"correctIndex":0}'::jsonb, '«Английский язык» nima degani?', array['Ingliz tili', 'Fransuz tili', 'Nemis tili', 'Rus tili'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q11', 'a1-m4-l2', 11, 'listening', '«Математика — мой любимый предмет» — «Matematika — menim sevimli fanim». «любимый» — sevimli.', '{"speakText":"Математика — мой любимый предмет.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Matematika — menim sevimli fanim.","Matematika — ertangi darsi.","Men matematikani tushunmayman.","Matematika — maktab nomi."],"correctIndex":0}'::jsonb, 'Математика — мой любимый предмет.', array['Matematika — menim sevimli fanim.', 'Matematika — ertangi darsi.', 'Men matematikani tushunmayman.', 'Matematika — maktab nomi.'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l2-q12', 'a1-m4-l2', 12, 'true_false', '«Физика» — maktab fanlaridan biri, musiqa darsi emas. Ikkala ham to''g''ri: fan ham, tarjima ham.', '{"ruText":"Физика — это школьный предмет.","uzTranslation":"Fizika — bu maktab fanlaridan biri.","isTrue":true}'::jsonb, 'Физика — это школьный предмет.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q01', 'a1-m4-l3', 1, 'multiple_choice', '«Учительница» — ayol o''qituvchi. «учитель» — erkak yoki umumiy o''qituvchi, «-ница» qo''shimchasi ayol jinsini bildiradi.', '{"prompt":"«Учительница» — bu kim?","promptLang":"uz","options":["O''quvchi","Ayol o''qituvchi","Direktor","Sinf mudiri"],"correctIndex":1}'::jsonb, '«Учительница» — bu kim?', array['O''quvchi', 'Ayol o''qituvchi', 'Direktor', 'Sinf mudiri'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q02', 'a1-m4-l3', 2, 'translation', '«Ученики» — o''quvchilar (ko''plik). Yagona shakli — «ученик» (o''quvchi), «ученица» — qiz o''quvchi.', '{"direction":"ru_to_uz","source":"Ученики","accepted":["o''quvchilar"]}'::jsonb, 'Ученики', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q03', 'a1-m4-l3', 3, 'word_selection', '«Задание» — vazifa, topshiriq. «урок» — dars, «кабинет» — xona, «доска» — dosha.', '{"promptUz":"Vazifa (topshiriq)","options":["урок","кабинет","доска","задание"],"correctIndex":3}'::jsonb, 'Vazifa (topshiriq)', array['урок', 'кабинет', 'доска', 'задание'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q04', 'a1-m4-l3', 4, 'listening', '«Учитель спрашивает ученика» — «O''qituvchi o''quvchidan so''raydi». «спрашивать» — so''ramoq, savol bermoq.', '{"speakText":"Учитель спрашивает ученика.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["O''quvchi o''qituvchiga javob beradi.","O''qituvchi o''quvchidan so''raydi.","O''qituvchi daftarni o''qiydi.","O''quvchi ruchka bilan yozadi."],"correctIndex":1}'::jsonb, 'Учитель спрашивает ученика.', array['O''quvchi o''qituvchiga javob beradi.', 'O''qituvchi o''quvchidan so''raydi.', 'O''qituvchi daftarni o''qiydi.', 'O''quvchi ruchka bilan yozadi.'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q05', 'a1-m4-l3', 5, 'fill_blank', '«Ученик отвечает» — o''quvchi javob beradi. Fe''l gapdagi otga qarab uchinchi shaxsda turadi: ученик → отвечает.', '{"sentence":"На уроке ученик ___ на вопросы учителя.","options":["отвечаете","отвечает","отвечают","отвечал"],"correctIndex":1}'::jsonb, 'На уроке ученик ___ на вопросы учителя.', array['отвечаете', 'отвечает', 'отвечают', 'отвечал'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q06', 'a1-m4-l3', 6, 'sentence_building', '«Учитель спрашивает ученика» — «O''qituvchi o''quvchidan so''raydi». «спрашивать» kishilik boshi bilan ishlatiladi: спрашивает кого? — ученика.', '{"correct":["Учитель","спрашивает","ученика","."],"distractors":["отвечает","книга","вчера"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q07', 'a1-m4-l3', 7, 'translation', '«O''quvchi javob beradi» — «Ученик отвечает». «отвечать на вопросы» — savollarga javob bermoq.', '{"direction":"uz_to_ru","source":"O''quvchi javob beradi.","accepted":["ученик отвечает","ученик отвечает?"]}'::jsonb, 'O''quvchi javob beradi.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q08', 'a1-m4-l3', 8, 'true_false', '«Управляет» — boshqaradi, «преподаёт» (o''qitadi) esa dars beradi. Bu ikki xil harakat, shuning uchun tarjima noto''g''ri.', '{"ruText":"Директор управляет школой.","uzTranslation":"Direktor maktabni o''qitadi.","isTrue":false}'::jsonb, 'Директор управляет школой.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q09', 'a1-m4-l3', 9, 'word_matching', 'Maktab odamlari: «учитель» — o''qituvchi, «ученик» — o''quvchi, «директор» — direktor, «класс» — sinf.', '{"pairs":[{"ru":"Учитель","uz":"O''qituvchi"},{"ru":"Ученик","uz":"O''quvchi"},{"ru":"Директор","uz":"Direktor"},{"ru":"Класс","uz":"Sinf"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q10', 'a1-m4-l3', 10, 'multiple_choice', 'O''qituvchi savol beradi, o''quvchi javob beradi. «отвечать» — javob bermoq, aynan o''quvchi buni bajaradi.', '{"prompt":"O''qituvchining savollariga kim javob beradi?","promptLang":"uz","options":["Dosha","Daftar","O''quvchi","Kabinet"],"correctIndex":2}'::jsonb, 'O''qituvchining savollariga kim javob beradi?', array['Dosha', 'Daftar', 'O''quvchi', 'Kabinet'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l3-q11', 'a1-m4-l3', 11, 'listening', '«Мой учитель очень добрый» — «Mening o''qituvchim juda mehribon». «добрый» — mehribon, yaxshi yurakli.', '{"speakText":"Мой учитель очень добрый.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Mening sinfim juda katta.","Mening o''quvchim juda tez yuguradi.","Mening kitobim juda qalin.","Mening o''qituvchim juda mehribon."],"correctIndex":3}'::jsonb, 'Мой учитель очень добрый.', array['Mening sinfim juda katta.', 'Mening o''quvchim juda tez yuguradi.', 'Mening kitobim juda qalin.', 'Mening o''qituvchim juda mehribon.'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q01', 'a1-m4-l4', 1, 'multiple_choice', '«Переменка» — tanaffus: uroklar orasidagi dam olish vaqti. «перемена» so''zidan kelgan.', '{"prompt":"«Переменка» nimani bildiradi?","promptLang":"uz","options":["Dars","Sinf","Tanaffus","Uy vazifasi"],"correctIndex":2}'::jsonb, '«Переменка» nimani bildiradi?', array['Dars', 'Sinf', 'Tanaffus', 'Uy vazifasi'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q02', 'a1-m4-l4', 2, 'translation', '«Первый урок начинается в восемь» — «Birinchi dars sakkizda boshlanadi». «в восемь» — sakkizda (soat ma''nosi).', '{"direction":"ru_to_uz","source":"Первый урок начинается в восемь.","accepted":["birinchi dars sakkizda boshlanadi","birinchi dars sakkizda boshlanadi?"]}'::jsonb, 'Первый урок начинается в восемь.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q03', 'a1-m4-l4', 3, 'fill_blank', '«Сейчас перемена» — «Hozir tanaffus». «сейчас» dan keyin ot nominativ (asosiy) padişasida turadi.', '{"sentence":"Сейчас ___.","options":["переменка","переменки","переменке","переменку"],"correctIndex":0}'::jsonb, 'Сейчас ___.', array['переменка', 'переменки', 'переменке', 'переменку'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q04', 'a1-m4-l4', 4, 'listening', '«Урок номер три начинается в десять» — «Uchinchi dars o''nida boshlanadi». «номер три» — uchinchi raqam.', '{"speakText":"Урок номер три начинается в десять.","promptUz":"Esiting va qaysi dars qachon boshlanishini tanlang.","options":["Ikkinchi dars o''nda boshlanadi.","Birinchi dars o''n beshda boshlanadi.","Uchinchi dars o''nida boshlanadi.","Uchinchi dars sakkizda boshlanadi."],"correctIndex":2}'::jsonb, 'Урок номер три начинается в десять.', array['Ikkinchi dars o''nda boshlanadi.', 'Birinchi dars o''n beshda boshlanadi.', 'Uchinchi dars o''nida boshlanadi.', 'Uchinchi dars sakkizda boshlanadi.'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q05', 'a1-m4-l4', 5, 'word_selection', '«Завтра» — ertaga. «сегодня» — bugun, «вчера» — kecha, «утром» — ertalab.', '{"promptUz":"Ertaga","options":["сегодня","вчера","завтра","утром"],"correctIndex":2}'::jsonb, 'Ertaga', array['сегодня', 'вчера', 'завтра', 'утром'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q06', 'a1-m4-l4', 6, 'sentence_building', '«Какой урок у тебя сейчас?» — «Hozir qaysi darsing?». Savol belgisi alohida token sifatida turadi.', '{"correct":["Какой","урок","у","тебя","сейчас","?"],"distractors":["вчера","учитель","дома"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q07', 'a1-m4-l4', 7, 'true_false', '«У нас сегодня пять уроков» — «Bugun bizda besh dars bor». «пять» — besh, tarjima to''g''ri.', '{"ruText":"У нас сегодня пять уроков.","uzTranslation":"Bugun bizda besh dars bor.","isTrue":true}'::jsonb, 'У нас сегодня пять уроков.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q08', 'a1-m4-l4', 8, 'translation', '«Darslar soat to''qqizda boshlanadi» — «Уроки начинаются в девять». «в девять» — to''qqizda (dars vaqti).', '{"direction":"uz_to_ru","source":"Darslar soat to''qqizda boshlanadi.","accepted":["уроки начинаются в девять","уроки начинаются в девять?"]}'::jsonb, 'Darslar soat to''qqizda boshlanadi.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q09', 'a1-m4-l4', 9, 'word_matching', 'Dars jadvali so''zlari: «урок» — dars, «переменка» — tanaffus, «кабинет» — xona, «номер» — raqam.', '{"pairs":[{"ru":"Урок","uz":"Dars"},{"ru":"Переменка","uz":"Tanaffus"},{"ru":"Кабинет","uz":"Xona"},{"ru":"Номер","uz":"Raqam"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q10', 'a1-m4-l4', 10, 'multiple_choice', '«В кабинете номер пять» — «beshinchi xonada». «в» + kabinet → «в кабинете» (joylashuv padişasi), «номер пять» — raqam besh.', '{"prompt":"«В кабинете номер пять» bu nimani bildiradi?","promptLang":"uz","options":["5-darsda","5-xonada","5-sinfda","5-kunda"],"correctIndex":1}'::jsonb, '«В кабинете номер пять» bu nimani bildiradi?', array['5-darsda', '5-xonada', '5-sinfda', '5-kunda'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l4-q11', 'a1-m4-l4', 11, 'listening', '«Завтра у нас урок географии» — «Ertaga bizda geografiya darsi bor». «завтра» — ertaga, «сегодня» — bugun.', '{"speakText":"Завтра у нас урок географии.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Ertaga bizda tarix darsi bor.","Ertaga bizda geografiya darsi bor.","Bugun bizda geografiya darsi bor.","Ertaga bizda musiqa darsi bor."],"correctIndex":1}'::jsonb, 'Завтра у нас урок географии.', array['Ertaga bizda tarix darsi bor.', 'Ertaga bizda geografiya darsi bor.', 'Bugun bizda geografiya darsi bor.', 'Ertaga bizda musiqa darsi bor.'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q01', 'a1-m4-l5', 1, 'multiple_choice', 'Dialogda Alina «Мне больше всего нравится музыка» deydi, ya''ni unga musiqa darsi eng yoqadi.', '{"prompt":"Ushbu dialogda qizga (Alinaga) qaysi fan eng ko''proq yoqadi?","promptLang":"uz","options":["Matematika","Geografiya","Musiqa","Fizika"],"correctIndex":2}'::jsonb, 'Ushbu dialogda qizga (Alinaga) qaysi fan eng ko''proq yoqadi?', array['Matematika', 'Geografiya', 'Musiqa', 'Fizika'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q02', 'a1-m4-l5', 2, 'translation', '«В каком ты классе?» — «Qaysi sinfdasan?». Maktab haqida suhbatda bu eng tabiiy savol.', '{"direction":"ru_to_uz","source":"В каком ты классе?","accepted":["qaysi sinfdasan","qaysi sinfdasan?"]}'::jsonb, 'В каком ты классе?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q03', 'a1-m4-l5', 3, 'listening', '«У нас уроки начинаются в восемь утра» — «Bizda darslar ertalab sakkizda boshlanadi». «в восемь» — sakkizda.', '{"speakText":"У нас уроки начинаются в восемь утра.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Darslar kechqurun oltida boshlanadi.","Darslar ertalab sakkizda boshlanadi.","Darslar ertalab oltida boshlanadi.","Darslar kechqurun sakkizda boshlanadi."],"correctIndex":1}'::jsonb, 'У нас уроки начинаются в восемь утра.', array['Darslar kechqurun oltida boshlanadi.', 'Darslar ertalab sakkizda boshlanadi.', 'Darslar ertalab oltida boshlanadi.', 'Darslar kechqurun sakkizda boshlanadi.'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q04', 'a1-m4-l5', 4, 'fill_blank', '«Мне нравится математика» — «Menga matematika yoqadi». «нравится» dan keyin ot nominativ padişasida turadi.', '{"sentence":"— Какой урок тебе нравится? — Мне нравится ___.","options":["математики","математику","математика","математике"],"correctIndex":2}'::jsonb, '— Какой урок тебе нравится? — Мне нравится ___.', array['математики', 'математику', 'математика', 'математике'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q05', 'a1-m4-l5', 5, 'true_false', 'Dialogda «Уроки начинаются в восемь утра» aytilgan, tarjima ham shu ma''noni beradi — to''g''ri.', '{"ruText":"Уроки начинаются в восемь утра.","uzTranslation":"Darslar ertalab sakkizda boshlanadi.","isTrue":true}'::jsonb, 'Уроки начинаются в восемь утра.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q06', 'a1-m4-l5', 6, 'sentence_building', '«Школа мне очень нравится» — «Maktab menga juda yoqadi». «нравится» 3-shaxsda: maktab (ot) → нравится.', '{"correct":["Школа","мне","очень","нравится","."],"distractors":["завтра","кабинет","семь"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q07', 'a1-m4-l5', 7, 'word_selection', '«Любимый предмет» — sevimli fan. «любимый» — sevgan, eng yoqqan narsa.', '{"promptUz":"Sevimli fan","options":["школьная тетрадь","любимый предмет","первый урок","переменка"],"correctIndex":1}'::jsonb, 'Sevimli fan', array['школьная тетрадь', 'любимый предмет', 'первый урок', 'переменка'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q08', 'a1-m4-l5', 8, 'word_matching', 'Maktab suhbati iboralari: «Мне нравится» — Menga yoqadi, «В каком классе» — Qaysi sinfdasan, «уроки начинаются» — darslar boshlanadi.', '{"pairs":[{"ru":"Мне нравится","uz":"Menga yoqadi"},{"ru":"В каком классе","uz":"Qaysi sinfdasan"},{"ru":"Уроки начинаются","uz":"Darslar boshlanadi"},{"ru":"Любимый предмет","uz":"Sevimli fan"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q09', 'a1-m4-l5', 9, 'translation', '«Menga matematika yoqadi» — «Мне нравится математика». «мне» (menga) — kim yoqishi bildiriladi.', '{"direction":"uz_to_ru","source":"Menga matematika yoqadi.","accepted":["мне нравится математика","мне нравится математика?"]}'::jsonb, 'Menga matematika yoqadi.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q10', 'a1-m4-l5', 10, 'multiple_choice', 'Dialogda «У нас уроки начинаются в восемь утра» deyilgan, ya''ni darslar sakkizda boshlanadi.', '{"prompt":"Ushbu dialogda darslar qachon boshlanadi?","promptLang":"uz","options":["Ikkida","To''qqizda","Oltida","Sakkizda"],"correctIndex":3}'::jsonb, 'Ushbu dialogda darslar qachon boshlanadi?', array['Ikkida', 'To''qqizda', 'Oltida', 'Sakkizda'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q11', 'a1-m4-l5', 11, 'listening', '«Мне больше нравится музыка» — «Menga ko''proq musiqa yoqadi». «больше» — ko''proq (solishtirish darajasi).', '{"speakText":"Мне больше нравится музыка.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Menga ko''proq matematika yoqadi.","Menga kamroq musiqa yoqadi.","Menga ko''proq musiqa yoqadi.","Menga ko''proq tarix yoqadi."],"correctIndex":2}'::jsonb, 'Мне больше нравится музыка.', array['Menga ko''proq matematika yoqadi.', 'Menga kamroq musiqa yoqadi.', 'Menga ko''proq musiqa yoqadi.', 'Menga ko''proq tarix yoqadi.'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m4-l5-q12', 'a1-m4-l5', 12, 'true_false', 'Dialogda darslar ikkida (в два дня) tugaydi, sakkizda emas. Sakkizda ular boshlanadi, shuning uchun tarjima noto''g''ri.', '{"ruText":"Уроки заканчиваются в восемь утра.","uzTranslation":"Darslar ertalab sakkizda tugaydi.","isTrue":false}'::jsonb, 'Уроки заканчиваются в восемь утра.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q01', 'a1-m5-l1', 1, 'multiple_choice', '«Завтракать» — «nonushta qilish». «Я завтракаю» = «Men nonushta qilaman», bu ertalabki ovqatlanish.', '{"prompt":"«Завтракаю» — bu qanday harakat?","promptLang":"uz","options":["Nonushta qilaman","Tushlik qilaman","Kechqurun ovqatlanaman","Uxlayman"],"correctIndex":0}'::jsonb, '«Завтракаю» — bu qanday harakat?', array['Nonushta qilaman', 'Tushlik qilaman', 'Kechqurun ovqatlanaman', 'Uxlayman'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q02', 'a1-m5-l1', 2, 'translation', '«Я встаю в семь утра» — «Men ertalab yettida turaman». Vaqt ko''rsatilganda «в» qo''shiladi: «в семь» = yetti da.', '{"direction":"ru_to_uz","source":"Я встаю в семь утра.","accepted":["men ertalab yettida turaman","men ertalab yettida uyg''onaman","men yettida turaman"]}'::jsonb, 'Я встаю в семь утра.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q03', 'a1-m5-l1', 3, 'word_selection', '«Обедать» — «tushlik qilish», «обедаю» = men tushlik qilaman. «завтракаю» — nonushta qilaman, «ужинаю» — kechqurun ovqatlanaman.', '{"promptUz":"Tushlik qilaman","options":["обедаю","ужинаю","завтракаю","работаю"],"correctIndex":0}'::jsonb, 'Tushlik qilaman', array['обедаю', 'ужинаю', 'завтракаю', 'работаю'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q04', 'a1-m5-l1', 4, 'fill_blank', '«Я» — birinchi shaxs birlik, fe''l -у (ю) qo''shimchasini oladi: «я встаю». «встаёшь» — «ты» (sening) uchun.', '{"sentence":"Я ___ в семь утра.","options":["встаёшь","встаю","встаём","встают"],"correctIndex":1}'::jsonb, 'Я ___ в семь утра.', array['встаёшь', 'встаю', 'встаём', 'встают'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q05', 'a1-m5-l1', 5, 'listening', '«Утром» — ertalab, «иду в школу» — maktabga boraman. «Завтракаю» — nonushta qilaman.', '{"speakText":"Утром я завтракаю и иду в школу.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Ertalab tushlik qilaman va dam olaman","Ertalab nonushta qilaman va maktabga boraman","Kechqurun nonushta qilaman va uyga boraman","Tunda maktabga boraman"],"correctIndex":1}'::jsonb, 'Утром я завтракаю и иду в школу.', array['Ertalab tushlik qilaman va dam olaman', 'Ertalab nonushta qilaman va maktabga boraman', 'Kechqurun nonushta qilaman va uyga boraman', 'Tunda maktabga boraman'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q06', 'a1-m5-l1', 6, 'word_matching', 'Kun vaqtlari: «утром» — ertalab, «вечером» — kechqurun. «обедаю» — tushlik qilaman, «сплю» — uxlayman.', '{"pairs":[{"ru":"утром","uz":"ertalab"},{"ru":"вечером","uz":"kechqurun"},{"ru":"обедаю","uz":"tushlik qilaman"},{"ru":"сплю","uz":"uxlayman"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q07', 'a1-m5-l1', 7, 'sentence_building', '«Я встаю в семь утра» — «Men ertalab yettida turaman». «утра» — «утро» so''zining kelishik (genitiv) shakli.', '{"correct":["Я","встаю","в","семь","утра","."],"distractors":["ужинаю","обедаю","ночью"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q08', 'a1-m5-l1', 8, 'true_false', '«Обед» — tushlik (12:00–15:00), shuning uchun «обедаю днём» = «Men tushlik qilaman» to''g''ri tarjima.', '{"ruText":"Я обедаю днём.","uzTranslation":"Men tushlik qilaman.","isTrue":true}'::jsonb, 'Я обедаю днём.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q09', 'a1-m5-l1', 9, 'multiple_choice', '«Ужинать» — «kechqurun ovqatlanish» (18:00–21:00). «Я ужинаю» = «Men kechqurun ovqatlanaman».', '{"prompt":"«Ужинаю» — bu qachon bajariladigan harakat?","promptLang":"uz","options":["Ertalab","Tushda","Kechqurun","Kechasi"],"correctIndex":2}'::jsonb, '«Ужинаю» — bu qachon bajariladigan harakat?', array['Ertalab', 'Tushda', 'Kechqurun', 'Kechasi'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q10', 'a1-m5-l1', 10, 'translation', '«Men kechqurun ovqatlanaman» — «Я ужинаю». «ужинать» fe''li kechki ovqatlanishni bildiradi.', '{"direction":"uz_to_ru","source":"Men kechqurun ovqatlanaman.","accepted":["я ужинаю","вечером я ужинаю"]}'::jsonb, 'Men kechqurun ovqatlanaman.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q11', 'a1-m5-l1', 11, 'listening', '«Ночью» — tunida («ночь» so''zidan). «Я сплю ночью» = «Men tunida uxlayman».', '{"speakText":"Я сплю ночью.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Men kunduzi uxlayman","Men kechqurun ovqatlanaman","Men tunida uxlayman","Men ertalab turaman"],"correctIndex":2}'::jsonb, 'Я сплю ночью.', array['Men kunduzi uxlayman', 'Men kechqurun ovqatlanaman', 'Men tunida uxlayman', 'Men ertalab turaman'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l1-q12', 'a1-m5-l1', 12, 'multiple_choice', '«Вечером» — kechqurun, kun oxiri. «утром» — ertalab, «днём» — kunduzi, «ночью» — tunida.', '{"prompt":"«Вечером я читаю книгу» gapidagi «вечером» nimani bildiradi?","promptLang":"uz","options":["Vaqtni — kechqurun","Joyni — kutubxonada","Og''irlikni — og''ir kitobni","Shaxsni — do''stim"],"correctIndex":0}'::jsonb, '«Вечером я читаю книгу» gapidagi «вечером» nimani bildiradi?', array['Vaqtni — kechqurun', 'Joyni — kutubxonada', 'Og''irlikni — og''ir kitobni', 'Shaxsni — do''stim'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q01', 'a1-m5-l2', 1, 'multiple_choice', '«Сколько времени?» — «Hozir soat necha?» degan savol. Javob: «Сейчас три часа» (Hozir uch soat).', '{"prompt":"«Сколько времени?» — bu qanday savol?","promptLang":"uz","options":["Kun qaysi hafta kuni","Soat necha bo''lgani","Yil necha oyga bo''lingan","Necha pul ketdi"],"correctIndex":1}'::jsonb, '«Сколько времени?» — bu qanday savol?', array['Kun qaysi hafta kuni', 'Soat necha bo''lgani', 'Yil necha oyga bo''lingan', 'Necha pul ketdi'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q02', 'a1-m5-l2', 2, 'translation', '«Сколько сейчас времени?» — vaqt so''ratish savoli. «Сколько» — «qancha», «сейчас» — «hozir».', '{"direction":"ru_to_uz","source":"Сколько сейчас времени?","accepted":["hozir qancha vaqt","hozir qancha vaqt bo''ldi","hozir soat nechada","hozir soat necha bo''ldi"]}'::jsonb, 'Сколько сейчас времени?', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q03', 'a1-m5-l2', 3, 'fill_blank', 'Soat aytganda sonlardan keyin «час» genitiv shaklini oladi: «три часа» (uch soat). «трёх» — kelishik shakli, bu yerda kerak emas.', '{"sentence":"Сейчас ___ часа.","options":["трёх","три","третьих","тридцать"],"correctIndex":1}'::jsonb, 'Сейчас ___ часа.', array['трёх', 'три', 'третьих', 'тридцать'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q04', 'a1-m5-l2', 4, 'word_selection', '«Час» — soat (vaqt birligi). «минута» — daqiqa, «секунда» — soniya, «день» — kun (kunning 24 soati).', '{"promptUz":"Soat (vaqt birligi)","options":["минута","секунда","час","день"],"correctIndex":2}'::jsonb, 'Soat (vaqt birligi)', array['минута', 'секунда', 'час', 'день'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q05', 'a1-m5-l2', 5, 'multiple_choice', '«Полчаса» — «yarim soat» (30 daqiqa). «пол» prefiksi «yarim» degan ma''noni beradi: «полчаса назад» — yarim soat oldin.', '{"prompt":"«Полчаса» so''zi nima degani?","promptLang":"uz","options":["Bir soat","Uch soat","O''n daqiqa","Yarim soat"],"correctIndex":3}'::jsonb, '«Полчаса» so''zi nima degani?', array['Bir soat', 'Uch soat', 'O''n daqiqa', 'Yarim soat'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q06', 'a1-m5-l2', 6, 'sentence_building', '«Я обедаю в два часа» — «Men soat ikkida tushlik qilaman». Soat bilan «в» + son + «часа» ishlatiladi.', '{"correct":["Я","обедаю","в","два","часа","."],"distractors":["ночью","семь","сплю"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q07', 'a1-m5-l2', 7, 'listening', '«Сейчас три часа» — «Hozir uch soat». Sonlardan keyin «час» genitiv shaklini oladi: «три часа», «пять часов».', '{"speakText":"Сейчас три часа.","promptUz":"Esiting va to''g''ri vaqtni tanlang.","options":["Hozir o''n daqiqa","Hozir uch yarim soat","Hozir uch soat","Hozir to''rt soat"],"correctIndex":2}'::jsonb, 'Сейчас три часа.', array['Hozir o''n daqiqa', 'Hozir uch yarim soat', 'Hozir uch soat', 'Hozir to''rt soat'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q08', 'a1-m5-l2', 8, 'true_false', '«Я ужинаю вечером» — «Men kechqurun ovqatlanaman». Berilgan tarjima boshqa harakatni (nonushta) bildiradi, shuning uchun u noto''g''ri.', '{"ruText":"Я ужинаю вечером.","uzTranslation":"Men ertalab nonushta qilaman.","isTrue":false}'::jsonb, 'Я ужинаю вечером.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q09', 'a1-m5-l2', 9, 'word_matching', 'Kun so''zlari: «сегодня» — bugun, «завтра» — ertaga, «вчера» — kecha. «в три часа» — uch soatda.', '{"pairs":[{"ru":"сегодня","uz":"bugun"},{"ru":"завтра","uz":"ertaga"},{"ru":"вчера","uz":"kecha"},{"ru":"в три часа","uz":"uch soatda"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q10', 'a1-m5-l2', 10, 'translation', '«Ertaga biz maktabga boramiz» — «Завтра мы идём в школу». «завтра» — ertaga, «идём» — boramiz (birinchi shaxs ko''plik).', '{"direction":"uz_to_ru","source":"Ertaga biz maktabga boramiz.","accepted":["завтра мы идём в школу","завтра мы идем в школу","завтра мы идём в школу?"]}'::jsonb, 'Ertaga biz maktabga boramiz.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q11', 'a1-m5-l2', 11, 'fill_blank', 'Soat ko''rsatilganda «в» qo''shiladi: «в девять часов» (soat to''qqizda). «на» vaqt bilan ishlatilmaydi.', '{"sentence":"Урок начинается ___ девять часов.","options":["на","до","в","с"],"correctIndex":2}'::jsonb, 'Урок начинается ___ девять часов.', array['на', 'до', 'в', 'с'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l2-q12', 'a1-m5-l2', 12, 'multiple_choice', '«Вчера» — kecha (o''tgan kun), «сегодня» — bugun, «завтра» — ertaga. Bu uch so''z kundalik suhbatda eng ko''p ishlatiladi.', '{"prompt":"«Вчера» so''zi qachon bildiradi?","promptLang":"uz","options":["Kecha — o''tgan kun","Ertaga — keyingi kun","Bugun — joriy kun","Har doim"],"correctIndex":0}'::jsonb, '«Вчера» so''zi qachon bildiradi?', array['Kecha — o''tgan kun', 'Ertaga — keyingi kun', 'Bugun — joriy kun', 'Har doim'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q01', 'a1-m5-l3', 1, 'multiple_choice', '«Она» — u (ayol kishi), fe''l -ет qo''shimchasini oladi: «она читает». «я читаю» esa «men o''qiyman».', '{"prompt":"«Она читает» — bu qaysi shaxs uchun aytiladi?","promptLang":"uz","options":["Men","U (ayol kishi)","Biz","Ular"],"correctIndex":1}'::jsonb, '«Она читает» — bu qaysi shaxs uchun aytiladi?', array['Men', 'U (ayol kishi)', 'Biz', 'Ular'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q02', 'a1-m5-l3', 2, 'translation', '«Они помогают маме» — «Ular mamaga yordam beradi». «помогать» doim dativ (кому? — kimga) bilan ishlatiladi.', '{"direction":"ru_to_uz","source":"Они помогают маме.","accepted":["ular mamaga yordam beradi","ular mamaga yordam beradilar","ular onasiga yordam beradi"]}'::jsonb, 'Они помогают маме.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q03', 'a1-m5-l3', 3, 'fill_blank', '«ты» bilan fe''l -ешь qo''shimchasini oladi: «ты пишешь» (sens yozasan). «пишет» — 3-shaxs (он/она) uchun.', '{"sentence":"Ты ___ письмо.","options":["пишешь","пишет","пишем","пишут"],"correctIndex":0}'::jsonb, 'Ты ___ письмо.', array['пишешь', 'пишет', 'пишем', 'пишут'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q04', 'a1-m5-l3', 4, 'word_selection', '«Он играет» — u (erkak) o''ynaydi. -ет qo''shimchasi 3-shaxs birlikka xos: «он играет».', '{"promptUz":"U o''ynaydi (erkak kishi)","options":["играем","играю","играет","играют"],"correctIndex":2}'::jsonb, 'U o''ynaydi (erkak kishi)', array['играем', 'играю', 'играет', 'играют'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q05', 'a1-m5-l3', 5, 'sentence_building', '«Мы хотим читать» — «Biz o''qishni xohlaymiz». «хотим» dan keyin fe''lning asosiy (infinitiv) shakli turadi.', '{"correct":["Мы","хотим","читать","."],"distractors":["пишешь","они","ученик"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q06', 'a1-m5-l3', 6, 'listening', '«Он играет в футбол» — «U futbol o''ynaydi». «играет» — 3-shaxs birlik shakli (он/она).', '{"speakText":"Он играет в футбол.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["U futbol to''pini ko''radi","U futbol o''ynaydi","U futbolchi","U futbol o''ynashni o''rgatadi"],"correctIndex":1}'::jsonb, 'Он играет в футбол.', array['U futbol to''pini ko''radi', 'U futbol o''ynaydi', 'U futbolchi', 'U futbol o''ynashni o''rgatadi'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q07', 'a1-m5-l3', 7, 'true_false', '«Я читаю» — birinchi shaxs birlik: men o''qiyman. «читает» bo''lganda «u o''qiydi» bo''lardi.', '{"ruText":"Я читаю книгу.","uzTranslation":"Men kitob o''qiyman.","isTrue":true}'::jsonb, 'Я читаю книгу.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q08', 'a1-m5-l3', 8, 'multiple_choice', 'Birinchi shaxs birlik: «я читаю» (men o''qiyman). «читаешь» — «ты» uchun, «читаем» — «мы» uchun.', '{"prompt":"«Читать» fe''lining birinchi shaxs birlik shakli qaysi?","promptLang":"uz","options":["читаешь","читает","читаю","читаем"],"correctIndex":2}'::jsonb, '«Читать» fe''lining birinchi shaxs birlik shakli qaysi?', array['читаешь', 'читает', 'читаю', 'читаем'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q09', 'a1-m5-l3', 9, 'translation', '«Ular maktabga boradilar» — «Они идут в школу». «идут» — 3-shaxs ko''plik shakli (они идут).', '{"direction":"uz_to_ru","source":"Ular maktabga boradilar.","accepted":["они идут в школу","они идут в школу?"]}'::jsonb, 'Ular maktabga boradilar.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q10', 'a1-m5-l3', 10, 'word_matching', 'Hozirgi zamon shakllari: «читаю» — men o''qiyman, «пишешь» — sen yozasan, «делает» — u qiladi, «идут» — ular boradilar.', '{"pairs":[{"ru":"читаю","uz":"o''qiyman"},{"ru":"пишешь","uz":"yozasan"},{"ru":"делает","uz":"qiladi"},{"ru":"идут","uz":"boradilar"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l3-q11', 'a1-m5-l3', 11, 'fill_blank', '«она» bilan fe''l -ет qo''shimchasini oladi: «она готовит обед» (u ovqat pishiradi). «готовлю» — birinchi shaxs (я) shakli.', '{"sentence":"Она ___ обед.","options":["готовим","готовят","готовлю","готовит"],"correctIndex":3}'::jsonb, 'Она ___ обед.', array['готовим', 'готовят', 'готовлю', 'готовит'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q01', 'a1-m5-l4', 1, 'multiple_choice', '«Домашняя работа» — uy vazifasi (dars topshirig''i). «Делаю домашнюю работу» — men uy vazifasini bajarayman.', '{"prompt":"«Делаю домашнюю работу» — bu qanday harakat?","promptLang":"uz","options":["Maktabga boraman","Uy vazifasini bajaraman","Kitob o''qiyman","Nonushta qilaman"],"correctIndex":1}'::jsonb, '«Делаю домашнюю работу» — bu qanday harakat?', array['Maktabga boraman', 'Uy vazifasini bajaraman', 'Kitob o''qiyman', 'Nonushta qilaman'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q02', 'a1-m5-l4', 2, 'translation', '«Я помогаю маме» — «Men mamamga yordam beraman». «помогать» dativ (кому? — kimga) bilan ishlatiladi: «маме» — mamaga.', '{"direction":"ru_to_uz","source":"Я помогаю маме.","accepted":["men mamaga yordam beraman","mamamga yordam beraman","men onamga yordam beraman"]}'::jsonb, 'Я помогаю маме.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q03', 'a1-m5-l4', 3, 'word_matching', 'Kundalik faoliyatlar: «гуляю» — sayr qilaman, «помогаю» — yordam beraman, «смотрю телевизор» — televizor ko''raman.', '{"pairs":[{"ru":"гуляю","uz":"sayr qilaman"},{"ru":"помогаю","uz":"yordam beraman"},{"ru":"смотрю телевизор","uz":"televizor ko''raman"},{"ru":"играю","uz":"o''ynayman"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q04', 'a1-m5-l4', 4, 'fill_blank', '«Я» bilan fe''l birinchi shaxs birlik shaklini oladi: «я играю» (men o''ynayman). «во дворе» — hovlida.', '{"sentence":"После уроков я ___ во дворе.","options":["играет","играем","играю","играют"],"correctIndex":2}'::jsonb, 'После уроков я ___ во дворе.', array['играет', 'играем', 'играю', 'играют'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q05', 'a1-m5-l4', 5, 'listening', '«Вечером» — kechqurun. «Я смотрю телевизор вечером» — «Men kechqurun televizor ko''raman».', '{"speakText":"Я смотрю телевизор вечером.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Men ertalab televizor ko''raman","Men tunida televizor ko''raman","Men kechqurun televizor ko''raman","Men dars qilaman"],"correctIndex":2}'::jsonb, 'Я смотрю телевизор вечером.', array['Men ertalab televizor ko''raman', 'Men tunida televizor ko''raman', 'Men kechqurun televizor ko''raman', 'Men dars qilaman'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q06', 'a1-m5-l4', 6, 'sentence_building', '«Я гуляю с другом» — «Men do''stim bilan sayr qilaman». «с» + kim = bilan (hamrohlik ma''nosi).', '{"correct":["Я","гуляю","с","другом","."],"distractors":["дома","смотрю","вечером"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q07', 'a1-m5-l4', 7, 'true_false', '«на кухне» — oshxonada, «помогаю маме» — mamamga yordam beraman. Tarjima to''g''ri.', '{"ruText":"Я помогаю маме на кухне.","uzTranslation":"Men oshxonada mamamga yordam beraman.","isTrue":true}'::jsonb, 'Я помогаю маме на кухне.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q08', 'a1-m5-l4', 8, 'multiple_choice', '«Гулять» — tashqarida sayr qilish, ochiq havoda yurish. «Я гуляю» — men sayr qilaman.', '{"prompt":"«Гуляю» so''zi qaysi ma''noda ishlatiladi?","promptLang":"uz","options":["Ovqatlanaman","Uxlayman","Yozaman","Sayr qilaman"],"correctIndex":3}'::jsonb, '«Гуляю» so''zi qaysi ma''noda ishlatiladi?', array['Ovqatlanaman', 'Uxlayman', 'Yozaman', 'Sayr qilaman'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q09', 'a1-m5-l4', 9, 'translation', '«Men televizor ko''raman» — «Я смотрю телевизор». «смотреть» — ko''rish, birinchi shaxs shakli «смотрю».', '{"direction":"uz_to_ru","source":"Men televizor ko''raman.","accepted":["я смотрю телевизор","я смотрю телевизор?"]}'::jsonb, 'Men televizor ko''raman.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q10', 'a1-m5-l4', 10, 'word_selection', '«Помогаю» — men yordam beraman («помогать» fe''li). «гуляю» — sayr qilaman, «читаю» — o''qiyman, «играю» — o''ynayman.', '{"promptUz":"Yordam beraman","options":["гуляю","читаю","помогаю","играю"],"correctIndex":2}'::jsonb, 'Yordam beraman', array['гуляю', 'читаю', 'помогаю', 'играю'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q11', 'a1-m5-l4', 11, 'true_false', '«днём» — kunduzi, «ночью» — tunida. Berilgan tarjima «ночью» ma''nosini bildiradi, shuning uchun u noto''g''ri.', '{"ruText":"Я играю в футбол днём.","uzTranslation":"Men tunda futbol o''ynayman.","isTrue":false}'::jsonb, 'Я играю в футбол днём.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l4-q12', 'a1-m5-l4', 12, 'listening', '«После уроков» — darslardan keyin, «помогаю маме» — mamamga yordam beraman.', '{"speakText":"После уроков я помогаю маме.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Darslardan keyin mamamga yordam beraman","Darslardan keyin futbol o''ynayman","Ertalab mamamga yordam beraman","Darslardan keyin uxlayman"],"correctIndex":0}'::jsonb, 'После уроков я помогаю маме.', array['Darslardan keyin mamamga yordam beraman', 'Darslardan keyin futbol o''ynayman', 'Ertalab mamamga yordam beraman', 'Darslardan keyin uxlayman'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q01', 'a1-m5-l5', 1, 'multiple_choice', '«Я встаю в семь» — men yettida turaman, «завтракаю» — nonushta qilaman. Demak, javob ertalabki tartib haqida.', '{"prompt":"«— Что ты делаешь утром? — Я встаю в семь и завтракаю.» Bu javob nima haqida?","promptLang":"uz","options":["Maktab darslari haqida","Ertalabki tartib: uyg''onish va nonushta haqida","Kechki ovqat haqida","Dam olish haqida"],"correctIndex":1}'::jsonb, '«— Что ты делаешь утром? — Я встаю в семь и завтракаю.» Bu javob nima haqida?', array['Maktab darslari haqida', 'Ertalabki tartib: uyg''onish va nonushta haqida', 'Kechki ovqat haqida', 'Dam olish haqida'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q02', 'a1-m5-l5', 2, 'translation', '«Потом» — «keyin». «Потом иду в школу» — «(Keyin) men maktabga boraman», «иду» — boraman.', '{"direction":"ru_to_uz","source":"Потом я иду в школу.","accepted":["keyin men maktabga boraman","keyin maktabga boraman","so''ng men maktabga boraman"]}'::jsonb, 'Потом я иду в школу.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q03', 'a1-m5-l5', 3, 'fill_blank', 'Javob beruvchi o''zi haqida gapiradi: «я иду» — men boraman. «идёт» — u (он/она) boradi.', '{"sentence":"— А потом? — Потом ___ в школу.","options":["идёт","идём","иду","идут"],"correctIndex":2}'::jsonb, '— А потом? — Потом ___ в школу.', array['идёт', 'идём', 'иду', 'идут'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q04', 'a1-m5-l5', 4, 'listening', '«Я встаю в семь» — men yettida turaman, «завтракаю» — nonushta qilaman. Ikkala harakat «и» (va) so''zi bilan bog''langan.', '{"speakText":"Я встаю в семь и завтракаю.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Men ertalab turaman va tushlik qilaman","Men kechqurun turaman va nonushta qilaman","Men o''nda turaman va maktabga boraman","Men yettida turaman va nonushta qilaman"],"correctIndex":3}'::jsonb, 'Я встаю в семь и завтракаю.', array['Men ertalab turaman va tushlik qilaman', 'Men kechqurun turaman va nonushta qilaman', 'Men o''nda turaman va maktabga boraman', 'Men yettida turaman va nonushta qilaman'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q05', 'a1-m5-l5', 5, 'word_matching', 'Dialog iboralari: «Что ты делаешь утром?» — Ertalab nima qilasan?, «А потом?» — Keyin-chi?, «домашняя работа» — uy vazifasi.', '{"pairs":[{"ru":"Что ты делаешь утром?","uz":"Ertalab nima qilasan?"},{"ru":"А потом?","uz":"Keyin-chi?"},{"ru":"Потом иду в школу","uz":"Keyin maktabga boraman"},{"ru":"домашняя работа","uz":"uy vazifasi"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q06', 'a1-m5-l5', 6, 'sentence_building', '«Вечером я делаю домашнюю работу» — «Men kechqurun uy vazifasini bajaraman». «домашнюю работу» — otning to''ldiruvchi (vinitiv) shakli.', '{"correct":["Вечером","я","делаю","домашнюю","работу","."],"distractors":["утром","завтракаю","школу"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q07', 'a1-m5-l5', 7, 'multiple_choice', '«А потом?» — «Keyin-chi? / So''ng nima?» degan savol. U suhbatda keyingi qadamni so''raydi.', '{"prompt":"«— А потом?» — bu savol nimani so''raydi?","promptLang":"uz","options":["Vaqtni (soat necha)","Joyni (qayerda)","Keyingi harakatni","Ismni"],"correctIndex":2}'::jsonb, '«— А потом?» — bu savol nimani so''raydi?', array['Vaqtni (soat necha)', 'Joyni (qayerda)', 'Keyingi harakatni', 'Ismni'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q08', 'a1-m5-l5', 8, 'translation', '«Men kechqurun uy vazifasini bajaraman» — «Вечером я делаю домашнюю работу». «делаю» — bajarayman («делать» fe''li).', '{"direction":"uz_to_ru","source":"Men kechqurun uy vazifasini bajaraman.","accepted":["вечером я делаю домашнюю работу","я делаю домашнюю работу вечером"]}'::jsonb, 'Men kechqurun uy vazifasini bajaraman.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q09', 'a1-m5-l5', 9, 'true_false', '«Я встаю в семь» — men yettida turaman, «завтракаю» — nonushta qilaman. Tarjima dialogda aynan shunday aytilgan.', '{"ruText":"Я встаю в семь и завтракаю.","uzTranslation":"Men yettida turaman va nonushta qilaman.","isTrue":true}'::jsonb, 'Я встаю в семь и завтракаю.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q10', 'a1-m5-l5', 10, 'word_selection', '«Потом» — keyin (keyingi harakat). «сейчас» — hozir, «вчера» — kecha, «всегда» — har doim.', '{"promptUz":"Keyin (keyingi qadam)","options":["сейчас","потом","вчера","всегда"],"correctIndex":1}'::jsonb, 'Keyin (keyingi qadam)', array['сейчас', 'потом', 'вчера', 'всегда'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q11', 'a1-m5-l5', 11, 'listening', '«Вечером» — kechqurun, «помогаю маме» — mamamga yordam beraman. «Вечером я помогаю маме» = «Men kechqurun mamamga yordam beraman».', '{"speakText":"Вечером я помогаю маме.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Ertalab mamamga yordam beraman","Kechqurun mamamga yordam beraman","Kechqurun futbol o''ynayman","Tunda maktabga boraman"],"correctIndex":1}'::jsonb, 'Вечером я помогаю маме.', array['Ertalab mamamga yordam beraman', 'Kechqurun mamamga yordam beraman', 'Kechqurun futbol o''ynayman', 'Tunda maktabga boraman'], '1'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m5-l5-q12', 'a1-m5-l5', 12, 'fill_blank', '«Я» bilan fe''l -у (ю) qo''shimchasini oladi: «я делаю» (men bajarayman). «делает» — 3-shaxs (он/она) uchun.', '{"sentence":"— Что ты делаешь вечером? — Я ___ домашнюю работу.","options":["делает","делаем","делаю","делают"],"correctIndex":2}'::jsonb, '— Что ты делаешь вечером? — Я ___ домашнюю работу.', array['делает', 'делаем', 'делаю', 'делают'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q01-1', 'a1-m6-l1', 1, 'multiple_choice', '«плохо» — «yomon». Misol: Мне сегодня плохо.', '{"prompt":"«плохо» so''zining tarjimasini top.","promptLang":"uz","options":["ikki","rahmat","yomon","kimyo"],"correctIndex":2}'::jsonb, '«плохо» so''zining tarjimasini top.', array['ikki', 'rahmat', 'yomon', 'kimyo'], '2'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q02-2', 'a1-m6-l1', 2, 'word_selection', '«папа» — «otam». Misol: Мой папа работает.', '{"promptUz":"«otam» — ruscha qanday?","options":["спасибо","ученик","аэропорт","папа"],"correctIndex":3}'::jsonb, '«otam» — ruscha qanday?', array['спасибо', 'ученик', 'аэропорт', 'папа'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q03-3', 'a1-m6-l1', 3, 'translation', '«дедушка» — «bobojon». Misol: Дедушка читает газету.', '{"direction":"ru_to_uz","source":"дедушка","accepted":["bobojon"]}'::jsonb, 'дедушка', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q04-4', 'a1-m6-l1', 4, 'translation', '«скидка» — «chegirma». Misol: Сегодня скидка двадцать процентов.', '{"direction":"uz_to_ru","source":"chegirma","accepted":["скидка"]}'::jsonb, 'chegirma', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q05-5', 'a1-m6-l1', 5, 'listening', 'Eshitilgan matn: «сын». To''g''ri tarjima: «o''g''lim».', '{"speakText":"сын","promptUz":"Eshiting va to''g''ri tarjimani tanlang.","options":["maydon","choy","rus tili","o''g''lim"],"correctIndex":3}'::jsonb, 'сын', array['maydon', 'choy', 'rus tili', 'o''g''lim'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
