insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m6-l1-q08-8', 'a1-m6-l1', 8, 'fill_blank', '«да» — «ha». To''liq gap: Да, я согласен.', '{"sentence":"___, я согласен.","options":["день","большой","родители","Да"],"correctIndex":3}'::jsonb, '___, я согласен.', array['день', 'большой', 'родители', 'Да'], '3'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
